INSERT INTO public.words (id, word, meaning, detailed_meaning, news_example, hint, related_words) VALUES
(161,'노동생산성/노동생산성지수','노동자 1인이 일정 기간 동안 산출해 내는 생산량으로 정의된다.','노동자 1인이 일정 기간 동안 산출해 내는 생산량으로 정의된다. 생산활동이 활발하면 노동생산성 증가율도 높아지는 관계가 있으므로 동 지수의 동향은 생산활동의 흐름을 파악하는 주요 지표로 이용되고 있다. 한편 임금이 노동생산성보다 더 빠르게 상승하면 단위노동비용이 증가하기 때문에 기업은 제품가격의 상승 압력을 받게 되고 그 결과 제품의 가격경쟁력이 떨어질 수 있다. 나라 전체로 확대되면 물가상승 압력이 커지면서 다른 나 라에 비해 수출제품의 가격경쟁력이 낮아지게 된다. 노동생산성지수 = 산출량지수/노동투입량지수×100','','ㄴㄷㅅㅅㅅ/ㄴㄷㅅㅅㅅㅈㅅ',ARRAY['단위노동비용']::text[]),
(162,'노동시장 긴장도','노동 수요(기업의 일자리 수)와 노동 공급(일할 사람의 수)의 균형 정도를 나타내는 지표로 서, 일자리에 비해 일할 사람이 얼마나 부족한지 또는 많은지를 보여준다.','노동 수요(기업의 일자리 수)와 노동 공급(일할 사람의 수)의 균형 정도를 나타내는 지표로 서, 일자리에 비해 일할 사람이 얼마나 부족한지 또는 많은지를 보여준다. 노동 수요가 공급에 비해 많은 경우 노동시장의 긴장도(tightness)는 높아지는데 이때 기업은 사람을 더뽑고 싶지만 구직자가 부족하게 되어 임금 상승 압력도 높아진다. 반면 노동 수요가 공급에 비해 적으면 노동시장의 긴장도는 낮아지며 실업자가 많아지고 임금도 정체 또는 하락할 가능성이 높다. 대표적인 지표로는 구인배수가 있으며 이외에 실업률, 임금상승률 등도 노동시장 긴장도를 파악할 수 있는 지표로 활용된다. 노동시장의 긴장도가 과도하게 높아지면 임금 인상압력이 누적되면서 물가상승 요인으로 작용할 수 있다. 반면에 노동시장의 긴장도가 과도하게 낮다는 것은 경기가 좋지 않고 실업자가 늘어난 상황을 의미한다.','','ㄴㄷㅅㅈㄱㅈㄷ',ARRAY['구인배수','실업률']::text[]),
(163,'녹색GDP','일반적으로 녹색GDP(Green GDP)는 한 나라의 국내총생산(GDP)에서 생산활동 중 발생하는 자연자원의 감소나 환경피해 등의 손실액을 공제한 것으로 이해된다.','일반적으로 녹색GDP(Green GDP)는 한 나라의 국내총생산(GDP)에서 생산활동 중 발생하는 자연자원의 감소나 환경피해 등의 손실액을 공제한 것으로 이해된다. 이는 기존의 GDP가 재화와 서비스를 많이 생산할수록 커지는 반면, 생산활동 과정에서 발생하는 자원고갈, 환경오염 등으로 인해 국민의 후생이 떨어지는 부정적인 효과를 전혀 반영하지 못하는 데서 대안으로 나온 것이다. 경제와 환경을 아우르는 지속가능한 발전의 개념이 처음 등장한 것은 1970년대이나 본격적으로 공론화되기 시작한 것은 1990년대 초반부터로, 2012년 UN은 환경과 경제를 통합적인 관점에서 정량적으로 분석할 수 있는 뉴스심리지수(NSI) 틀인 환경경제통합계정(SEEA; System of Environmental-Economic Accounting)을 국민계정의 부속계정형태로 채택하고, 2021년 생태계 통계 체계의 표준으로 생태계계정 (EA; Ecosystem Accounting)을 채택 후 각국에 이의 이행을 권고한 바 있다. 현재 우리나라는 SEEA의 환경보호지출계정을 도입하여 운영 중이다.','','ㄴㅅ','{}'::text[]),
(164,'녹색기후기금(GCF)','개발도상국의 온실가스 감축과 기후변화 대응을 지원하기 위하여 만들어진 UN 산하의 국제금융기구이다.','개발도상국의 온실가스 감축과 기후변화 대응을 지원하기 위하여 만들어진 UN 산하의 국제금융기구이다. 유엔기후변화협약(UNFCCC)에 따라 운용되고 있는 기존의 지구환경기금(GEF; Global Environment Facility)과 적응기금(AF; Adaptation Fund)의 경우기금 규모가 개발도상국의 수요를 충족하지 못하는 데다 기후변화뿐 아니라 생물 다양성, 수자원 보호 등에도 지원해야 하는 등의 한계가 있었다. 이에 따라 2010년 12월 멕시코칸쿤에서 개최된 제16차 기후변화 당사국 총회(COP; Conference of the Parties)에서 녹색기후기금(GCF; Green Climate Fund)을 새로 설립하기로 합의하였다. 2012년 카타르 도하에서 열린 제18차 총회에서 한국의 인천 송도국제도시에 사무국을 설치하기로 확정하고 2013년 12월에 공식 출범하였다. 2025년 6월 말 현재 회원국으로부터 총 168억달러의 기금을 조성하였다. 녹색기후기금의 운영을 담당하는 이사회는 24개국으로 구성되며 선진국과 개발도상국이 동수로 참여하고 있다.','','ㄴㅅㄱㅎㄱㄱ()','{}'::text[]),
(165,'뉴스심리지수(NSI)','뉴스심리지수(NSI; News Sentiment Index)는 경제분야 뉴스기사에 나타난 경제심리를 지수화한 것이다.','뉴스심리지수(NSI; News Sentiment Index)는 경제분야 뉴스기사에 나타난 경제심리를 지수화한 것이다. 뉴스는 경제상황에 대한 사실과 함께 이와 관련한 긍정 혹은 부정적인감성을 포함하고 있는데, 이러한 감성이 경제주체의 심리와 연관성이 높아 경기를 파악할수 있는 유용한 정보를 제공한다. 한국은행은 2022년 1월부터 뉴스심리지수(일별 및 월별지수)를 개발하여 한국은행 경제통계시스템(ECOS)을 통해 공표하고 있다. NSI는 인터넷 포털사이트의 경제분야 뉴스기사에서 표본문장을 추출한 뒤 각 문장에 나타난 긍정, 부정, 중립의 감성을 기계학습(machine learning) 방법으로 분류하고 긍정과 부정문장수의 차이를 계산하여 지수화한 지표이다. NSI는 100보다 크면 뉴스기사에 나타난 경제심리가 과거 장기평균보다 낙관적인 것으로, 100보다 작으면 비관적인 것으로 해석된다.','','ㄴㅅㅅㄹㅈㅅ()','{}'::text[]),
(166,'단기금융시장','단기금융시장(Money Market)은 금융기관, 기업 등 경제주체들이 단기적인 자금수급 불균형을 조절하기 위하여 통상 만기 1년 이내의 단기 금융상품을 거래하는 시장이다.','단기금융시장(Money Market)은 금융기관, 기업 등 경제주체들이 단기적인 자금수급 불균형을 조절하기 위하여 통상 만기 1년 이내의 단기 금융상품을 거래하는 시장이다. 이 시장은 기업의 시설자금이나 장기운전자금 조달을 목적으로 발행되는 주식, 채권 등이 거래되는 자본시장에 대응하여 자금시장이라고도 불린다. 현재 우리나라 단기금융시장에는 콜시장, 기업어음(CP)시장, 양도성예금증서(CD)시장, 환매조건부증권매매(RP)시장, 전자단기사채시장, 통화안정증권시장(만기 1년 이내) 등이 있다. 이 시장은 중앙은행의 통화정책이 파급되는 시발점이 되기 때문에 매우 중요한 시장이다. 중앙은행의 정책금리 변경은 단기금융시장 금리 변화를 통해 장기금리 및 금융기관 예금·대출금리에 영향을 미치고 궁극적으로 생산, 물가 등 실물경제에 영향을 미친다. 일반적으로 단기금융시장이 발달되어 있으면 활발한 재정거래를 통해 통화정책의 파급효과가 원활히 이루어진다. 이외에도 단기금융시장은 단기자금을 손쉽게 조달하거나 운용할 수 있으므로 경제주체들에게일시적인 단기자금 수급 불균형에 따른 유동성 관리를 용이하게 해주며, 단기금융상품은 만기가 짧아 장기금융상품에 비하여 금리변동위험이 크지 않고 유동성도 높으므로 금융상품 보유에 따른 위험을 관리할 수 있는 수단을 제공하기도 한다.','','ㄷㄱㄱㅇㅅㅈ',ARRAY['장기금융시장(자본시장)']::text[]),
(167,'단리/복리','단리(Simple Interest)는 원금에 대해서만 약정된 이율과 기간을 곱하여 이자를 산출하는 방식이다.','단리(Simple Interest)는 원금에 대해서만 약정된 이율과 기간을 곱하여 이자를 산출하는 방식이다. 예를 들어 1억원을 만기 2년, 연 3%에 단리로 정기예금을 하는 경우 2년후원리금은 106백만원[100백만원(1+3%×2)]이다. 이때 실효수익률은 연 3%(6%/2)로 표면금리와 동일하다. 반면 복리(Compound Interest)는 일정 기간마다 발생한 이자를 원금에 합산한 후 그 합산금액에 대한 이자를 다시 계산하는 방식이다. 예를 들어 1억원을 만기 2년, 연 3%에 6개월 복리(6개월마다 이자를 원금에 가산)로 정기예금을 하는 경우 2년후 원리금은 106.14백만원[100백만원(1+3%/2)^4]이다. 이 경우 실효수익률은 연 3.07%(6.14%/2)이다. 위 예에서는 복리로 예금했을 때 단리보다 14만원의 이자를 더 받게 된다. 복리효과는 간단히 말해 이자가 이자를 낳는 원리이기 때문에 시간이 지날수록추가되는 이자부분이 커지면서 전체 저축 원리금이 기하급수적으로 늘어나는 원리이다. 따라서 저축기간이 짧으면 복리효과가 크지 않은 반면 저축기간이 길면 길수록 약간의 금리 차이(복리가 단리보다 높으므로)에도 이자금액이 크게 벌어지게 된다. 복리에서는 72 법칙이라는 것이 있다. 이자가 복리로 붙을 경우 원리금이 커지기 때문에 원리금이 두 배 (100%)로 불어나는데 필요한 저축기간과 수익률의 곱이 100%가 아니라 72%만 되면 된 다는 것이다. 위 예에서 보면 1억원을 2억원으로 불리는데 걸리는 기간은 단리의 경우 약 33년(100백만원/3백만원)이 소요되는 반면 복리의 경우 24년(72%/3%)이 소요되어 1억원을 2억원으로 불리는데 걸리는 기간이 복리가 단리보다 9년이나 짧다. 우리가 꾸준한 저축을 강조하는 이유는 저축의 경제적 성과 뒤에는 복리효과가 숨어있기 때문이다.','','ㄷㄹ/ㅂㄹ','{}'::text[]),
(168,'단위노동비용','단위노동비용이란 산출물 한 단위를 생산하는데 소요되는 노동비용을 말한다.','단위노동비용이란 산출물 한 단위를 생산하는데 소요되는 노동비용을 말한다. 일반적으로 단위노동비용은 상품의 국제경쟁력을 비교하는 데 있어 중요한 지표가 된다. 국제경쟁력은 가격경쟁력과 기술수준이나 브랜드 등 비가격경쟁력으로 나누어 볼 수 있는데 단기적으로는 수출상품의 가격경쟁력이 바로 해당 상품의 국제경쟁력을 결정한다고 볼 수 있다. 한편 단위노동비용은 임금과 노동생산성의 밀접한 관계로 표시할 수 있는데, 이는 다 음을 보면 쉽게 알 수 있다. 노동비용 시간당 노동비용×총노동시간단위노동비용 = = 총산출량 총산출량시간당 노동비용 시간당 노동비용 = = 총산출량/총노동시간 노동생산성이 관계로부터 시간당 노동비용(임금)의 상승 또는 노동생산성의 악화는 단위노동비용을 증가시키며, 반대로 임금의 하락 또는 노동생산성의 개선은 단위노동비용을 감소시키는 효과를 갖는다는 것을 알 수 있다.','','ㄷㅇㄴㄷㅂㅇ',ARRAY['노동생산성/노동생산성지수','총산출']::text[]),
(169,'단일금리방식/복수금리방식','경쟁입찰에 따른 발행금리 결정방식에는 복수금리(Conventional)방식과 단일금리 (Dutch)방식이 있다.','경쟁입찰에 따른 발행금리 결정방식에는 복수금리(Conventional)방식과 단일금리 (Dutch)방식이 있다. 복수금리(가격)방식은 각 낙찰자가 입찰시 제시한 금리(가격)를 발행금리(발행가격)로 하는 방식이며, 단일금리(단일가격)방식은 각 낙찰자가 입찰시 제시한 금리(가격) 중 최고금리(최저가격)를 발행금리(발행가격)로 하는 방식이다. 유동성 흡수 시에는 금융기관의 자금운용을 제약한다는 점을 고려하여 금융기관에 유리하게 단일금리방식을 적용하는 반면 유동성 지원 시에는 금융기관의 입찰 독려를 위해 유인을 제공할 필요가 없으므로 복수금리결정방식을 적용하는 경향이 있다. 현재 통화안정증권 발행시 입찰시행 전에 발행금리 결정방식을 공고하고 있으며 입찰참가자에게 더욱 유리한 단일금리방식을 주로 사용한다. 그리고 공개시장운영 수단으로 환매조건부증권(RP) 매매를 경쟁입찰 방식으로 진행할 경우 RP매각 시에는 단일금리방식을, RP매입 시에는 복수금리방식을 주로 사용하고 있다.','','ㄷㅇㄱㄹㅂㅅ/ㅂㅅㄱㄹㅂㅅ',ARRAY['통화안정증권']::text[]),
(170,'담보인정비율(LTV)','주택담보대출 취급 시 담보가치(주택가격) 대비 대출 취급 가능금액의 비율 (Loan-To- Value ratio)을 의미한다.','주택담보대출 취급 시 담보가치(주택가격) 대비 대출 취급 가능금액의 비율 (Loan-To- Value ratio)을 의미한다. 예를 들어 아파트 감정가격이 5억원이고 담보인정비율(LTV)이','','ㄷㅂㅇㅈㅂㅇ()','{}'::text[]),
(171,'당일결제/익일결제/익익일결제','70%이면 금융기관으로부터 3억 5천만원의 주택담보대출을 받을 수 있다.','70%이면 금융기관으로부터 3억 5천만원의 주택담보대출을 받을 수 있다. 「은행업감독업무시행세칙」에서는 “담보인정비율 = [(담보대출금액+선순위채권+임차보증금 및 최우선변제 소액임차보증금)/담보가치×100” 방식으로 산정하도록 하고 있다. 여기서 담보가치는 ① 국세청의 기준시가 ② 감정평가법인 등의 감정평가액 ③ 한국부동산원의 층별ㆍ호별 격차율 지수로 산정한 가격 ④ KB부동산시세의 ‘일반평균가’ 중 금융기관 자율로 선택하여 적용한다. 당초 LTV 규제는 은행권을 중심으로 내규에 반영하여 자율적으로 시행 ㄷ 해 오다가 금융기관의 경영 안정성 유지, 부동산 투기 억제 등을 위한 주택담보대출 규모의 관리 필요성이 제기되면서 2002년 9월 감독규제 수단으로 도입되었다. 이후 가계부채증가 억제 및 부동산경기 조절 등 거시건전성정책 수단으로 활용되고 있으며, 주택 소재지(규제·비규제), 차주 특성(무주택·다주택·생애최초 등) 및 대출목적(주택구입·임대사업등)별로 세분화하여 차등 적용되고 있다. 한편, 금융기관은 주택담보대출 취급시 담보인정비율(LTV)과 함께 차주의 부채상환능력을 나타내는 총부채상환비율(DTI), 총부채원리금상환비율(DSR) 등도 고려하여 대출규모를 결정한다.','','ㄷㅇㄱㅈ/ㅇㅇㄱㅈ/ㅇㅇㅇㄱㅈ',ARRAY['선물환거래']::text[]),
(172,'대기성 여수신제도','대기성 여수신제도(Standing Facilities)는 금리 중심 통화정책 운영방식 하에서 단기시장금리의 과도한 변동을 억제하기 위한 정책수단이다.','대기성 여수신제도(Standing Facilities)는 금리 중심 통화정책 운영방식 하에서 단기시장금리의 과도한 변동을 억제하기 위한 정책수단이다. 대기성 여신제도는 중앙은행이 차입기관의 자금사정이나 자금용도 등에 대한 제한 없이 단기자금을 제공하되 시장금리보다 다소 높은 금리로 제공하는 담보대출제도를 말한다. 차입은행이 기본적인 자산건전성등의 요건을 충족하는 한 차입수요에 따라 제한 없이 자금을 공급한다는 점에서 금융기관의 단기 유동성 부족을 해소하는 안전판 기능을 수행한다. 따라서 대기성 여신제도 하에 서 단기시장금리는 대기성 여신금리보다 높아지기 어렵기 때문에 대기성 여신금리가 단기시장금리의 상한기능을 수행한다. 이에 비해 대기성 수신제도는 중앙은행이 은행의 여유자금을 금액 제한 없이 수신하여 정책금리보다 낮은 금리를 지급하는 제도로서 대기성수신금리는 단기시장금리의 하한기능을 수행한다.','','ㄷㄱㅅㅇㅅㅅㅈㄷ','{}'::text[]),
(173,'대량지급','대량지급(Direct Credit)은 은행지로 업무의 한 유형으로서 급여, 연금, 배당금 등과 같이 일시 또는 정기적으로 발생하는 다수의 고객을 대상으로 동시에 이루어지는 거래를 위하여…','대량지급(Direct Credit)은 은행지로 업무의 한 유형으로서 급여, 연금, 배당금 등과 같이 일시 또는 정기적으로 발생하는 다수의 고객을 대상으로 동시에 이루어지는 거래를 위하여 공공기관이나 대기업 등 이용기관의 예금계좌에서 다수의 수취인 예금계좌로 지정된 날짜에 자금을 이체하는 업무이다. 이를 이용하면 하나의 거래은행을 통해서도 전국 모든은행의 수취인 예금계좌로 자금을 이체할 수 있다.','','ㄷㄹㅈㄱ',ARRAY['지로(GIRO)','입금이체']::text[]),
(174,'대손충당금적립비율','은행을 포함하여 기업이 보유하는 채권 중에서 거래상대방의 부도 등으로 회수가 어려워손실이 발생할 수 있는데, 이러한 손실을 충당하기 위해 미리 비용으로 처리해서 사내에 유보해둔 자금을…','은행을 포함하여 기업이 보유하는 채권 중에서 거래상대방의 부도 등으로 회수가 어려워손실이 발생할 수 있는데, 이러한 손실을 충당하기 위해 미리 비용으로 처리해서 사내에 유보해둔 자금을 대손충당금이라고 한다. 「은행업 감독규정」에서는 은행들에게 차주의 채무상환능력 등을 감안하여 자산건전성을 분류하고 이에 따라 대손충당금을 적립하도 록 하고 있다. 은행이 적립한 대손충당금을 비교적 회수가 어려운 고정이하여신 금액으로 대외의존도/수출입의존도/무역의존도 나눈 비율을 대손충당금 적립비율이라고 한다.','','ㄷㅅㅊㄷㄱㅈㄹㅂㅇ',ARRAY['고정이하여신비율']::text[]),
(175,'대안정기','2002년 4월 전미경제연구소(NBER; National Bureau of Economic Research) 연례세미나에서 미국 하버드대 스톡(J. Stock) 교수와 프린스턴대 왓슨(M.…','2002년 4월 전미경제연구소(NBER; National Bureau of Economic Research) 연례세미나에서 미국 하버드대 스톡(J. Stock) 교수와 프린스턴대 왓슨(M. Watson) 교수가 주요국의 경기순환이 달라졌음을 설명하면서 처음 사용한 용어이다. 1980년대 중반 이후 2007년 금융위기 이전까지 약 20년간 일본을 제외한 주요 선진국에서 산출량, 인플레이 션 등 거시변수의 변동성이 크게 감소하면서 경제가 안정을 누린 기간을 지칭한다. 대안정기(great moderation)는 다양한 원인에서 비롯된 것으로 분석되고 있는데, 2004년 미국 연준의 버냉키(Ben S. Bernanke) 의장은 ‘대안정기(The Great Moderation)’라는 제목의 연설에서 “경제제도, 기술, 사업관행, 경제의 구조적인 특징 변화가 경제의 충격을 흡수하는 능력을 향상시켰고, 주요국 중앙은행들이 인플레이션을 잘 통제하는 등 통화정책의 성과로 경제적 안정이 증대되었으며 경제에 타격을 주는 충격이 적었던 행운도 따랐기 때문”이라고 지적한 바 있다. 그러나 2008년 글로벌 금융위기가 발생하면서 대안정기가 허상 혹은 착시였으며 금융시장에 대한 과신과 과잉 레버리지로 위기를 초래하였다는 주장도 제기되었다.','','ㄷㅇㅈㄱ',ARRAY['골디락스경제']::text[]),
(176,'대외의존도/수출입의존도/무역의존도','국민경제가 가계, 기업, 정부 이외에 국외부문과의 상호작용에 의해서도 영향을 받게 되는 경제체제를 개방경제체제라고 한다.','국민경제가 가계, 기업, 정부 이외에 국외부문과의 상호작용에 의해서도 영향을 받게 되는 경제체제를 개방경제체제라고 한다. 대외의존도란 개방경제체제 하의 국민경제에서 국외부문과의 거래가 차지하는 크기를 측정하는 지표이다. 수출입의존도 혹은 무역의존도라고 하기도 한다. 구체적으로 대외의존도는 국민소득에서 수출과 수입이 차지하는 비중으로 계산된다. 이때 국민소득 지표로 우리나라는 공식적으로 국민총소득(GNI)을 이 용하나 분석 목적에 따라 국내총생산(GDP)을 쓰기도 한다. 대외의존도가 높으면 높을수록 국외부문의 여건 변화가 한 국가의 국민경제에 미치는 영향이 커지게 됨을 의미한다. 세계화 시대에서 경제의 대외의존도 확대는 불가피한 측면이 있으나 지나치게 높은 대외의존도는 궁극적으로 국민경제의 구조적 불안정 요인으로 작용할 수 있는 위험 또한 포함 하고 있다.','','ㄷㅇㅇㅈㄷ/ㅅㅊㅇㅇㅈㄷ/ㅁㅇㅇㅈㄷ',ARRAY['국내총생산(GDP)','국민총소득(GNI)']::text[]),
(177,'대외지급준비자산','대외지급준비자산이란 한 나라의 통화 당국이 경제에 큰 영향을 미치지 않고 언제든지 대외 지급에 충당할 수 있도록 보유하고 있는 준비자산(금, SDR, IMF position 및 보유 외화)을…','대외지급준비자산이란 한 나라의 통화 당국이 경제에 큰 영향을 미치지 않고 언제든지 대외 지급에 충당할 수 있도록 보유하고 있는 준비자산(금, SDR, IMF position 및 보유 외화)을 말한다. 대외지급준비자산은 외국 채권자가 받아들일 수 있는 수용성, 외국 화폐단위로서 표현될 수 있는 가치의 확실성, 통화 당국이 즉각 활용할 수 있는 유동성을 갖추어야 한다. 한편 중앙은행이나 정부가 국제수지 불균형 보전이나 외환시장 안정을 위해 언제든지 사용할 수 있도록 보유하고 있는 대외지급준비자산을 외환보유액이라고 한다. 외환보유액은 긴급 시 국민경제의 안전판일 뿐만 아니라 환율을 안정시키고 국가 신인도를 높이는 데 기여한다. 외환보유액을 산출하는 방식은 국가별로 상이한데, 대체로 우리나라와 대다수 선진국에서는 공적 외환당국이 보유한 순외화자산만을 계상하고 있다.','','ㄷㅇㅈㄱㅈㅂㅈㅅ',ARRAY['외환보유액','IMF 포지션','특별인출권(SDR)']::text[]),
(178,'대체비용리스크','미래 특정일자에 종료될 거래의 상대방이 거래를 취소하거나 파산할 경우, 결제일 전에 결제가 이행되지 못할 가능성을 감안하여 다른 거래로 대체하는 과정에서 발생할 비용리스크를 의미한다.','미래 특정일자에 종료될 거래의 상대방이 거래를 취소하거나 파산할 경우, 결제일 전에 결제가 이행되지 못할 가능성을 감안하여 다른 거래로 대체하는 과정에서 발생할 비용리스크를 의미한다. 거래 당사자는 상대방의 거래 취소 또는 부도 등으로 자신의 포지션을 헤지하지 못하거나 현재 포지션에서 발생하는 미실현 이익을 얻지 못할 수 있으며 이 에 따른 리스크 노출액은 현행 시장가격으로 원거래를 대체하는데 드는 비용과 동일하다. 한 예로 외환거래의 최종결제 이전에 거래상대방이 거래를 취소하거나 파산할 경우 해당거래를 다른 거래로 대체하는 과정에서 불리한 환율 변동으로 인해 비용이 발생할 리스크를 들 수 있다. 다른 예를 들면, A은행이 B은행과 금리파생상품을 계약하고 동 거래를 헤지하기 위해 C은행과 다른 금리파생상품을 계약하였다가, 결제일 전에 C은행이 파산으로 대출채권 분할매각결제불이행이 발생할 경우 A은행은 대체비용리스크에 직면하게 된다. 2008년 9월 리먼브라더스사가 파산하면서 결제불이행 사태가 대량으로 발생했던 것이 대표적인 사례이 다. 이와 같이 대체비용리스크는 거래상대방의 거래 취소 또는 부도 등이 빈번한 외환거래, 파생상품 거래 등에서 주로 발생한다.','','ㄷㅊㅂㅇㄹㅅㅋ',ARRAY['보완재']::text[]),
(179,'대출금 출자전환','금융기관이 차주기업에 대한 대출채권을 동 기업의 주식과 교환하는 것으로서 금융기관의 차주기업에 대한 관계가 채권자에서 주주로 변하게 된다.','금융기관이 차주기업에 대한 대출채권을 동 기업의 주식과 교환하는 것으로서 금융기관의 차주기업에 대한 관계가 채권자에서 주주로 변하게 된다. 금융기관은 기업에 대한 경영감시기능을 높여 경영정상화 후 배당을 받거나 주식매각을 통한 시세차익을 획득할 수있으며, 기업은 부채비율 하락과 원리금 상환부담 감소로 경영정상화를 도모할 수 있다. 반면 출자전환 기업이 도산할 경우 출자금 회수가 불가능하게 되어 오히려 금융기관의 부실화가 가속화 될 수 있을 뿐만 아니라 부실기업의 도산위험이 금융기관에 전가되어 금융기관의 신인도가 저하될 수 있다는 부정적 측면도 있다.','','ㄷㅊㄱㅊㅈㅈㅎ','{}'::text[]),
(180,'대출채권 분할매각','대출채권 유동화 방법의 하나로서, 대출을 취급한 금융기관이 대출채권의 전부 또는 일부를 타인(참가자 또는 투자자)에게 매각하는 것을 말한다.','대출채권 유동화 방법의 하나로서, 대출을 취급한 금융기관이 대출채권의 전부 또는 일부를 타인(참가자 또는 투자자)에게 매각하는 것을 말한다. 금융기관이 차주와의 채권 채무관계를 유지한 채 원리금 수취권만을 양도하게 되어 있어 참가자가 대출채권에 대한 위험을 부담하게 된다. 즉 금융기관이 채무자로부터 원리금을 회수하는 경우에 한하여 원리금을 수취할 수 있게 된다. 동 거래는 채권을 처분한 대출 금융기관이 여전히 계약상의 채권자로 남아 있어, 채무자에게 대출채권 분할매각 사실을 통지하지 않아도 되는 장점이 있다. 더블딥경기가 두 번(double) 떨어진다(dip)는 뜻으로, 경기침체가 발생한 후 잠시 경기가 회복되다가 다시 경기침체로 접어드는 연속적인 침체 현상을 의미한다. 더블딥(Double Dip) 은 2001년 미국 모건스탠리사의 이코노미스트였던 로치(S. Roach)가 미국경제를 진단하면서 처음 사용한 용어로, 경기순환의 모습이 영문자 “W”를 닮았다 해서 “W자형 경기변동”(또는 “W자형 불황”)이라고도 한다. 일반적으로 경기침체가 2분기 연속 마이너스 성장을 보이는 경우를 말하므로 더블딥은 경기침체가 발생하고 잠시 회복 기미가 관측되다 다 시 2분기 연속 마이너스 성장에 빠지는 것으로, 1980년대 초 있었던 미국의 경기침체는 더블딥의 예로 자주 거론된다. 당시 미국경제는 석유파동의 영향 등으로 1980년 1월부터 7월까지 침체에 빠졌으나 이후 1981년 1/4분기까지 빠르게 성장하였는데, 연준이 인플레이션을 제압하기 위하여 금리를 빠르게 올림에 따라 1981년 7월부터 1982년 11월까지 다시 불황에 빠지는 경기침체를 경험한 바 있다.','','ㄷㅊㅊㄱㅂㅎㅁㄱ',ARRAY['경기']::text[]),
(181,'도덕적 해이','도덕적 해이는 거래당사자의 한쪽이 상대보다 양질의 정보를 더 많이 가지고 있는 상태 (정보의 비대칭성)에서 계약이 이루어진 후에 나타날 수 있는 문제이다.','도덕적 해이는 거래당사자의 한쪽이 상대보다 양질의 정보를 더 많이 가지고 있는 상태 (정보의 비대칭성)에서 계약이 이루어진 후에 나타날 수 있는 문제이다. 예를 들면 주주와 전문경영인, 은행과 차입자 간의 계약을 들 수 있다. 전문경영인은 회사의 경영상황에 대해 주주보다 더 많은 정보를 가지고 주주가 아닌 자신의 이익을 극대화하는 경우가 있을 수 있다. 이를 전문경영인의 도덕적 해이라 한다. 또한 은행으로부터 대출을 받은 차입자가 계약대로 차입금을 적절한 투자에 사용하는지를 은행이 정확히 확인할 수 없기독점/과점때문에 발생하는 문제는 차입자의 도덕적 해이에 해당한다. 도덕적 해이를 해결하기 위해서는 정보의 비대칭성을 완화하거나, 전문경영인이나 차입자(대리인)의 이해를 주주나 은행(주인)의 이해와 일치시키는 장치를 마련하는 게 중요하다. 여기서 주인과 대리인의 이해가 일치하지 않아 발생하는 문제를 주인-대리인 문제 또는 대리인 문제라고 한 다. 한편 정보의 비대칭성 상태에서 계약이 이루어지기 전에 나타날 수 있는 문제로는 역선택이 있다. ㄷ','','ㄷㄷㅈㅎㅇ',ARRAY['역선택','정보의 비대칭성']::text[]),
(182,'도드-프랭크법','동 법은 미국에서 2008년의 글로벌 금융위기가 발생한 이후 이러한 위기의 재발을 방지하기 위해 오바마 정부가 제안한 내용을 반영하여 2010년 7월에 제정되었으며 1930 년대 대공황기의…','동 법은 미국에서 2008년의 글로벌 금융위기가 발생한 이후 이러한 위기의 재발을 방지하기 위해 오바마 정부가 제안한 내용을 반영하여 2010년 7월에 제정되었으며 1930 년대 대공황기의 금융개혁 이후 가장 광범위한 개혁방안을 담고 있다. 동 법의 공식 명칭은 「도드-프랭크 월가 개혁 및 소비자보호법(Dodd-Frank Wall Street Reform and Consumer Protection Act)」이다. 동 법안을 입안한 미상원 은행위원회 위원장 크리스 도드(Chris Dodd)와 미하원 금융서비스위원회 위원장 바니 프랭크(Barney Frank) 의 이름을 따서 명명되었다. 동 법은 금융시스템리스크 예방을 위한 금융안정감시위원회 (Financial Stability Oversight Council) 신설, 금융회사 정리절차 개선, 대마불사(大馬 不死) 관행을 막기 위한 대형 은행의 자본확충 의무화, 금융감독기구별 역할 정비, 금융소비자 보호 강화를 위한 소비자금융보호국(Bureau of Consumer Financial Protection) 신설, 장외파생금융상품 등에 대한 규제·감독 강화 등 매우 광범위한 금융규제방안을 담고 있으며, 특히 은행의 자기계정투자(proprietary trading)를 금지하는 볼커룰(Volcker Rule)을 포함하고 있어 1930년대 글래스-스티걸법의 부활이라는 평가를 받고 있다.','','ㄷㄷㅍㄹㅋㅂ',ARRAY['죄수의 딜레마','카르텔']::text[]),
(183,'동남아시아국가연합(ASEAN)','동남아시아의 지역협력기구로서 아세안(ASEAN; Association of South-East Asian Nations)이라고도 부른다.','동남아시아의 지역협력기구로서 아세안(ASEAN; Association of South-East Asian Nations)이라고도 부른다. 동남아시아 지역협력의 촉진, 외국의 간섭 배제 및 역내 국가의 평화와 안정 수호, 경제·사회·문화·기술 등 각 분야에서의 상호원조를 설립목적으로 하고 있다. 회원국은 1967년 8월 창설 당시 필리핀, 말레이시아, 싱가포르, 인도네시아, 태국 등 5개국이었으나 1984년 브루나이, 1995년 베트남, 1997년 라오스와 미얀마, 1999년 캄보디아가 차례로 가입하면서 총 10개국으로 늘어났다. 주요 기구로는 정상회의, 외교장관회의, 상임위원회와 함께 상설 사무국을 인도네시아 자카르타에 두고 있다. 1997년 창설 30주년을 맞아 공동의 비전으로 ASEAN Vision 2020을 도입하였고 이 에 따라 아세안정치보안공동체, 아세안경제공동체, 아세안사회문화공동체를 축으로 하는 역내 통합을 추구하고 있으며 2015년 12월 아세안경제공동체를 출범시킴으로써 단일시장 구축을 추진하고 있다. 이와 함께 역외 국가들과도 대화 관계를 수립해 경제·안보·문화 등의 영역에서 협력을 도모하고 있는데 이러한 대화 상대국은 한국을 비롯하여 미국,','','ㄷㄴㅇㅅㅇㄱㄱㅇㅎ()','{}'::text[]),
(184,'동아시아 외환위기','1997년 태국을 시작으로 인도네시아, 말레이시아, 필리핀, 한국 등 동아시아 국가들에서 발생한 외환위기를 말한다.','1997년 태국을 시작으로 인도네시아, 말레이시아, 필리핀, 한국 등 동아시아 국가들에서 발생한 외환위기를 말한다. 1997년 중반 이후 태국의 바트(baht)화 가치가 고정환율제도 포기의 영향으로 폭락하고 그 여파로 인도네시아, 필리핀, 말레이시아의 통화가치가 급락한 데 이어 11월에는 한국이 환율 급등 및 외화유동성 부족에 직면하는 등 동아시아 국가 들은 외환시장 마비, 급격한 자본유출 등으로 큰 어려움을 겪었다. 이들 국가별 외환위기의 원인 및 정책 대응은 각국 여건에 따라 상이하기 때문에 일률적으로 규정하기는 어렵다. 다만 한국을 비롯하여 태국, 인도네시아, 필리핀은 위기 극복과정에서 국제통화기금 (IMF)으로부터 자금지원을 받는 대신 IMF의 정책권고에 따른 데 비해 말레이시아는 IMF 지원을 받지 않고 독자적으로 극복정책을 추진하였다. 이들 국가는 1998년 중반 이후 경기가 점차 회복되면서 1999년에는 대체로 위기상황으로부터 벗어났다. 한국의 경우 대기업의 연쇄 부도, 경상수지 적자 확대, 단기외채 급증 등의 대내적 요인 외에 개도국 시장에 대한 불안감 확산으로 인한 해외 채권자들의 자금회수 등 대외적 요인이 겹치면서 외화유동성이 크게 부족해지자 1997년 12월 IMF에 구제금융을 신청하여 IMF로부터 195 억 달러, 세계은행(IBRD)과 아시아개발은행(ADB)으로부터 각각 70억 달러와 37억 달러를 지원받았다.','','ㄷㅇㅅㅇㅇㅎㅇㄱ',ARRAY['경기순응성']::text[]),
(185,'동행종합지수','개별 경제지표로는 파악하기 어려운 국민경제의 총체적인 경기수준을 파악하기 위하여경기종합지수를 작성한다.','개별 경제지표로는 파악하기 어려운 국민경제의 총체적인 경기수준을 파악하기 위하여경기종합지수를 작성한다. 경기종합지수는 선행종합지수, 동행종합지수, 후행종합지수등 세 종류가 작성되는데 기준년도 수치가 100이 되도록 하여 산출하고 있다. 동행종합지수는 광공업생산지수, 서비스업생산지수(도소매업 제외), 건설기성액, 소매판매액지수, 내수출하지수, 수입액, 비농림어업취업지수 등 경기순환과 함께 변동하는 7개 개별지표를 등록발행가공·종합하여 만들어진다. 다만 현재의 경기상황을 판단하는 데는 동행종합지수에서 추세변동을 제거한 동행종합지수 순환변동치를 주로 사용한다. 경기종합지수는 경기의 종합적인 움직임을 가늠할 수 있다는 장점이 있으나 작성상 한계가 있는 만큼 개별 경제지표의 움직임도 함께 살펴보아야 한다.','','ㄷㅎㅈㅎㅈㅅ',ARRAY['경기종합지수','후행종합지수']::text[]),
(186,'듀레이션','듀레이션(Duration)이란 채권에서 발생하는 현금흐름의 가중평균만기로 투자자금의 평균회수기간을 의미한다.','듀레이션(Duration)이란 채권에서 발생하는 현금흐름의 가중평균만기로 투자자금의 평균회수기간을 의미한다. 듀레이션은 채권의 현금흐름 발생기간(t)에 각 시점 현금흐름의 현재가치가 채권가격에서 차지하는 비중을 가중치로 곱하여 산출한다. 채권의 발행만기는 최종 현금흐름 시점을 나타내는 데 비해 듀레이션은 만기 이전에 발생하는 모든 현금흐름을 감안한 평균회수기간이기 때문에 만기 이전에 현금흐름이 발생하는 이표채권의 듀레이션은 항상 채권의 발행만기보다 짧다. 할인채의 경우 현금흐름이 만기시점에 한번만 존재하므로 듀레이션과 만기가 같다. 듀레이션은 채권의 만기, 표면금리, 만기수익률등에 따라 결정된다. 먼저 듀레이션은 일종의 만기 개념이므로 만기에 비례하여 길어진다. 또한 채권의 표면금리가 높을수록 초기에 많은 금액이 회수되므로 듀레이션은 짧아진다. 마지막으로 현금흐름의 현재가치를 산정하는 할인율로 쓰이는 만기수익률이 높을수록 만기에 가까운 현금흐름의 가중치가 상대적으로 작아져 듀레이션은 짧아진다. 한편 듀레이션은 채권가격의 이자율탄력성을 나타낸다. 즉 듀레이션(D), 채권가격(p), 만기수익률(r) 사이에는 (dp/p) = -〔dr/(1+r)〕× D의 관계가 성립한다. 따라서 듀레이션은 채권투자에 따른 이자율위험(시장이자율 변동에 따른 채권가격의 변동률)을 나타내는 척도이자중요한 리스크 관리수단으로 활용되고 있다.','','ㄷㄹㅇㅅ','{}'::text[]),
(187,'등록발행','등록발행이란 채권을 실물발행(physical issue)하지 않고 한국예탁결제원 등 등록기관이 관리하는 채권등록부에 채권자의 성명, 주소, 채권금액 등 권리내역을 등록(book-entry)…','등록발행이란 채권을 실물발행(physical issue)하지 않고 한국예탁결제원 등 등록기관이 관리하는 채권등록부에 채권자의 성명, 주소, 채권금액 등 권리내역을 등록(book-entry) 함으로써 증서의 점유 없이도 채권자의 법적 권리를 보장하는 것을 말한다. 채권자는 등록절차를 마침으로써 채권자로서의 권리가 확보되며, 채권의 매매, 질권 및 담보권의 설정, 신탁재산의 표시 등은 채권등록부 기재를 통하여 해당 채권의 발행자 및 제3자에게대항할 수 있다. 채권 발행자 입장에서는 실물 발행비용이 절감되고, 원리금을 지급할 때실물 확인절차를 생략할 수 있는 등 업무처리가 간편해지는 이점이 있다. 채권자의 입장에서도 실물보관에 따른 위험부담이 없고 보관비용이 절감되는 이점이 있다. 현재 대부분의 채권은 실물발행 없이 등록발행되고 있다. 국고채 등 대부분의 국채와 통화안정증권은 한국은행이, 금융채·회사채 등 여타 채권은 한국예탁결제원이 각각 등록업무를 담당하고 있다. CD의 경우 2006년 6월부터 CD 등록발행제가 시행됨에 따라 은행들이 금융기관을 대상으로 CD를 발행하는 경우 대부분 CD를 실물발행하지 않고 한국예탁결제원을 통해등록발행하고 있다.','','ㄷㄹㅂㅎ','{}'::text[]),
(188,'디레버리징','디레버리징(Deleveraging)은 부채를 축소하는 것을 말한다.','디레버리징(Deleveraging)은 부채를 축소하는 것을 말한다. 미시경제 측면에서 보면, 가 계나 기업 등 개별 경제주체의 재무상태표에서 부채의 비중을 낮추는 것을 의미한다. 경기가 호황일 때는 상대적으로 낮은 금리로 자금을 차입하여 수익성이 높은 곳에 투자해빚을 상환하고도 수익을 많이 낼 수 있는 레버리지(leverage)가 효과적인 투자기법이 된 다. 그러나 경기가 불황일 때는 자산가치가 급격히 하락하여 수익성이 낮아지고 금리가 상대적으로 높아지게 되므로 부채를 상환, 정리, 감축하는 디레버리징이 더 큰 손실을 줄이는 투자기법이 된다. 디레버리징을 위해서는 경제주체는 자산을 매각하거나 증자를 통해 자금을 조달해야 한다. 디레버리징은 자금난을 겪고 있는 민간부문에게는 고통스러운과정인데, 이는 자산을 할인가격에 매각하여 심각한 손실을 떠안아야 하기 때문이다. 거시경제 측면에서 보면, 경제 전체의 디레버리징은 민간과 정부 등 여러 부문에서의 동시다발적인 부채 수준의 감축을 뜻한다. 통상 국민계정에서 GDP 대비 총부채 비율의 하락으로 측정된다. 2008년 글로벌 금융위기 이후 세계 각국에서 나타난 경제 전체의 디레버리징은 거시경제 전반에 심대한 영향을 미쳤으며, 종종 경기불황으로 이어졌다. 민간부문의 디레버리징을 상쇄하는 과정에서 정부부채가 증가하는 현상이 많은 나라에서 관찰되었다.','','ㄷㄹㅂㄹㅈ',ARRAY['레버리지 효과']::text[]),
(189,'디스인플레이션','물가수준이 지속적으로 높아지고 있으나 물가상승률은 둔화되는 현상을 말한다.','물가수준이 지속적으로 높아지고 있으나 물가상승률은 둔화되는 현상을 말한다. 예를 들어 소비자물가상승률이 2020년 5.0%, 2021년 3.5%, 2022년 2.0%라고 할 경우 매년 물가상승률이 0보다 크기 때문에 상품과 서비스의 가격 수준은 지속적으로 상승하고 있지만 상승률은 점차 낮아지고 있는데 이때 디스인플레이션(Disinflation)이 진행 중이라고 한다. 디스인플레이션은 단기간에 그치면 크게 걱정할 일은 아니다. 예를 들어 에너지가 격 하락이나 생산성 증대 등 공급요인으로 인한 일시적인 물가상승률의 둔화는 경제에 이 로울 수 있다. 그러나 디스인플레이션이 계속돼 물가상승률의 추가적인 하락이 전망되는 경우에는 가계와 기업이 소비와 투자를 미룸으로써 수요의 위축을 초래하여 경기침체가 초래될 수 있다. 또한 물가상승률이 낮아졌지만 임금 상승률이 더 낮다면 실질구매력 저하로 수요 위축이 심화될 수 있다. 이 같은 상황에서는 디스인플레이션이 지속되지 않도 록 정책당국은 통화·재정정책 등을 활용하여 사전에 잘 대응할 필요가 있다.','','ㄷㅅㅇㅍㄹㅇㅅ',ARRAY['디플레이션','통화정책']::text[]),
(190,'디커플링/커플링','디커플링(Decoupling)이란 탈동조화라고 번역할 수 있는데, 어떤 나라나 지역의 경제가 인접한 다른 국가나 전반적인 세계 경제의 흐름과는 다른 모습을 보이는 현상을 말한다.','디커플링(Decoupling)이란 탈동조화라고 번역할 수 있는데, 어떤 나라나 지역의 경제가 인접한 다른 국가나 전반적인 세계 경제의 흐름과는 다른 모습을 보이는 현상을 말한다. 디커플링의 예로는 금융위기 이후 신흥국가나 유로지역 국가 등이 미국 경제와 다른 모습을 보이는 것을 들 수 있다. 이외에도 주가나 금리, 환율 등 일부 경제 변수의 흐름이 국가 간 또는 특정 국가 내에서 서로 다른 흐름을 보이는 현상도 디커플링이라고 할 수 있다. 예를 들어 국가 간의 경우 미국의 주가와 한국의 주가가 다른 방향으로 움직이거나, 한 국가 내에서의 경우 주가가 하락함에도 해당국 통화가 강세 현상을 보이는 경우 등을 들 수있다. 반대로 한 나라 또는 지역의 경제가 인접한 다른 국가나 세계 경제 흐름과 유사한 흐름을 보이는 것을 커플링(동조화, Coupling)이라 한다.','','ㄷㅋㅍㄹ/ㅋㅍㄹ','{}'::text[]),
(191,'디플레이션','물가가 지속적으로 하락하는 현상을 말한다.','물가가 지속적으로 하락하는 현상을 말한다. 디플레이션이 발생하는 원인은 생산물의 과 잉공급, 자산거품의 붕괴, 과도한 통화 긴축정책, 생산성 향상 등 다양하다. 그러나 궁극적으로는 유통되는 통화의 양이 재화 및 서비스의 양보다 적기 때문에 화폐가치는 상승하고 반대로 물가는 하락하는 디플레이션이 발생한다는 점에 이견이 없다. 디플레이션이 발생하면 통화의 가치는 상승하고 실물자산의 가치는 하락함에 따라 인플레이션과 반대 방향으로 소득 및 부의 비자발적 재분배가 발생한다. 이외에도 실질금리 상승에 따른 총수요 감소, 실질임금 상승에 따른 고용 및 생산 감소, 소비지출 연기에 따른 경제활동 위축, 부채디플레이션에 따른 총수요 감소, 통화정책 및 재정정책 등 정책적 대응 제약, 디플레이션 악순환 가능성 등의 문제를 일으킬 수 있다.','','ㄷㅍㄹㅇㅅ',ARRAY['인플레이션','피셔효과']::text[]),
(192,'래퍼곡선','래퍼곡선미국의 경제학자 래퍼(A. Laffer)가 제시한 조세수입과 세율 간의 관계를 나타낸 곡선을 말한다.','래퍼곡선미국의 경제학자 래퍼(A. Laffer)가 제시한 조세수입과 세율 간의 관계를 나타낸 곡선을 말한다. 래퍼는 세율이 0%에서 100%로 증가할 때 조세수입은 상승하다가 정점에 이른후 다시 하강한다면서, 세율(t)을 수평축에 조세수입(T)을 수직축에 놓고 이들의 관계를 그려보면 아래 그림과 같이 “역 U자 모양의 곡선”이 된다고 주장하였다. 래퍼곡선(Laffer curve)에 따르면 세율이 높아지면 초기에는 세수가 늘어나나 일정 수준(t*)이 넘으면 오히려 감소하므로 현재의 세율이 세수가 가장 많은 수준(t*)을 넘지 않았다면 세수증대를 위해서는 세율을 올려야 하며 반대로 현재의 세율이 세수가 가장 많은 수준을 넘었다면 세율 인하가 세수증대에 도움이 된다. 래퍼곡선은 미국 레이건 정권의 감세정책을 뒷받침한 이론적 근거로 널리 이용되었으나 조세수입을 극대화시키는 최적세율이 어느 정도 수준인지는 정확하게 제시하지 못한다는 한계가 있다.','','ㄹㅍㄱㅅ',ARRAY['조세부담률']::text[]),
(193,'레그테크','레그테크(RT; RegTech, Regulatory Technology)는 금융업 등 산업 전반에 걸쳐 혁신정보기술(IT)과 규제를 결합하여 규제관련 요구사항 및 절차를 효율적으로 처리하는…','레그테크(RT; RegTech, Regulatory Technology)는 금융업 등 산업 전반에 걸쳐 혁신정보기술(IT)과 규제를 결합하여 규제관련 요구사항 및 절차를 효율적으로 처리하는 기술또는 회사를 뜻한다. 이는 금융서비스 산업의 새 영역이자 일종의 핀테크(FinTech)이다. 레그테크회사들은 수작업의 자동화, 분석·보고절차의 연결, 데이터 품질 개선, 데이터에 대한 전체적인 시각의 창출, 절차관련 앱(application)에 의한 데이터 자동 분석, 핵심 사업에 대한 의사결정 및 규제당국 앞 송부용 보고서 생산에 초점을 맞춘다.','','ㄹㄱㅌㅋ',ARRAY['‌핀테크','고객확인절차(KYC)','블록체인','분산원장기술']::text[]),
(194,'레버리지 효과','비율 공시를 의무화하였으며 은행들은 2018년 1월부터 최저 레버리지비율(3%)도 준수해야 한다.','비율 공시를 의무화하였으며 은행들은 2018년 1월부터 최저 레버리지비율(3%)도 준수해야 한다. 이 밖에도 글로벌 시스템적 중요 은행(G-SIB)에게는 2022년 1월부터 시스템적중요도에 따라 국별로 추가 레버리지비율이 적용되고 있다. 이는 위험가중자산 기반 자기자본비율 규제에서 G-SIB에 대해 부과하고 있는 추가자본 규제와의 일관성을 갖추기 위한 것으로 G-SIB은 자기자본비율 규제상 부과되는 추가자본의 50%만큼 상향 조정된 레버리지비율을 준수해야 한다. 예를 들어 2%의 추가자본이 부과된 G-SIB이 준수해야 할레버리지비율은 최저 레버리지비율 3%에 추가자본의 50%에 해당하는 1%가 가산된 4% 가 된다. G-SIB이 동 레버리지비율을 준수하지 못할 경우, 추가자본의 미준수시와 동일 ㄹ 하게 이익배분이 제한된다. 우리나라는 레버리지비율을 「은행업감독규정」에서 단순기본자본비율로 정의하고 있으며 2015년 1분기부터 보조지표로 공시된 후 2018년부터 동 규제(3% 이상)가 시행되었으며 2020년 1월부터는 인터넷전문은행에도 적용되었다.','','ㄹㅂㄹㅈㅎㄱ',ARRAY['디레버리징']::text[]),
(195,'레버리지비율/단순기본자본비율','레버리지비율(Leverage Ratio)은 ‘[기본자본(Tier 1) / 총익스포저(난외자산 포함)] × 100’으로 정의된다.','레버리지비율(Leverage Ratio)은 ‘[기본자본(Tier 1) / 총익스포저(난외자산 포함)] × 100’으로 정의된다. 분자의 자본은 바젤Ⅲ 기준 기본자본(Tier 1)을 사용하며 분모의 총익스포저는 자기자본비율을 산정할 경우에 적용되는 위험가중자산과는 달리 명목가액을 기준으로 하여 산출한다. 자기자본비율 규제 하에서 은행은 호황기에 보유자산의 위험가 중치를 낮게 설정함으로써 외형상 높은 자기자본 수준을 유지하면서 레버리지를 확대할수 있었다. 이 경우 위기 발생시 급격한 디레버리징(자산처분, 부채상환)이 발생하여 위기가 증폭되는 악순환이 발생할 수 있는데, 레버리지비율 규제는 이러한 자기자본비율 규제의 문제점을 보완한다고 할 수 있다. 바젤은행감독위원회(BCBS)는 2015년 1월부터 레버리지','','ㄹㅂㄹㅈㅂㅇ/ㄷㅅㄱㅂㅈㅂㅂㅇ','{}'::text[]),
(196,'로렌츠곡선','1905년 미국의 통계학자인 로렌츠(M. Lorenz)가 소득의 불평등 정도를 측정하기 위해제안한 것으로, 인구의 누적비율을 가로축에 소득의 누적점유율을 세로축에 놓고 이들의 관계를 그림으로…','1905년 미국의 통계학자인 로렌츠(M. Lorenz)가 소득의 불평등 정도를 측정하기 위해제안한 것으로, 인구의 누적비율을 가로축에 소득의 누적점유율을 세로축에 놓고 이들의 관계를 그림으로 표시한 곡선을 말한다. 모든 사람의 소득이 일정하다면 인구가 누적되어도 소득 누적액이 일정할 것이므로 로렌츠 곡선(Lorenz Curve)은 아래 그림의 OO′선과 같은 대각선이 된다. 반면 소득이 불평등하다면 처음에는 소득이 적은 사람들의 누적액이 더해져 그래프의 기울기가 완만하다가 뒤로 갈수록 소득이 많은 사람들의 누적액이 더해지면서 가파른 모양의 아래로 늘어진 곡선이 된다. 극단적으로 한 사람이 모든 소득을 다 가지고 있는 경우에는 OTO′선과 같은 모양이 된다. 따라서 로렌츠 곡선이 OO′선에 가 까워질수록 분배상태가 평등하고, OTO′선에 가까워질수록 불평등 정도가 높다고 판단할수 있다. 로렌츠 곡선은 한 나라의 소득분배 상태를 그림으로 볼 수 있다는 장점이 있으나 그 정도를 정량적으로 표시할 수 없다는 단점이 있다. 소득분배 상태를 정량적으로 파악하기 위해서는 지니계수를 이용하여야 한다. 지니계수는 아래 그림의 대각선과 로렌츠곡선 사이의 면적을 대각선 아래 삼각형 면적 전체로 나눈 것으로, 소득분배가 완전히 평등 하다면 대각선과 로렌츠곡선 사이의 면적이 0이 되어 지니계수는 0이 된다. 반대로 소득분배가 완전히 불평등하다면 대각선과 로렌츠곡선 사이의 면적이 대각선 아래 전체 면적과 같게 되므로 지니계수는 1이 된다. 100 0′ 소득 누적점유율소득의 완전 균등분배를 나타내는 대각선 ( 로렌츠 곡선 % ) T 0 인구의 누적비율(%) 100','','ㄹㄹㅊㄱㅅ',ARRAY['지니계수']::text[]),
(197,'로보어드바이저','로보어드바이저(Robo-Advisor)는 로봇(robot)과 자문가(advisor)의 합성어이다.','로보어드바이저(Robo-Advisor)는 로봇(robot)과 자문가(advisor)의 합성어이다. 이는 인공지능 알고리즘, 빅데이터 등을 활용하여 투자자의 투자성향·리스크 선호도·목표수익률 등을 분석하고 그 결과를 바탕으로 투자자문·자산운용 등 온라인 자산관리서비스를 제공하는 것이다. 서비스 제공 과정에서 비용으로 작용하는 사람의 개입을 최소화함으로써기존 자산관리서비스보다 더 낮은 최소투자금액과 더 싼 수수료로 소액 자산을 가진 일반개인도 더 쉽게 접근할 수 있게 되었다. ㄹ','','ㄹㅂㅇㄷㅂㅇㅈ',ARRAY['빅데이터','상장지수펀드(ETF)']::text[]),
(198,'리디노미네이션','리디노미네이션(Redenomination) 또는 ‘화폐단위 변경’이란 구매력이 다른 새로운 화폐단위를 만들어 현재의 화폐단위로 표시된 가격, 증권의 액면가, 예금·채권·채무 등 일체의 금액을…','리디노미네이션(Redenomination) 또는 ‘화폐단위 변경’이란 구매력이 다른 새로운 화폐단위를 만들어 현재의 화폐단위로 표시된 가격, 증권의 액면가, 예금·채권·채무 등 일체의 금액을 법정비율(교환비율)에 따라 일률적으로 조정하여 새로운 화폐단위로 표기 및호칭하는 것을 의미한다. 보통 리디노미네이션은 지속적인 인플레이션으로 인해 재화와 서비스의 교환가치를 화폐로 나타내는 숫자가 많아서 초래되는 계산 및 회계기장 등의 불편을 해소할 목적으로 시행된다. 또한 자국 통화의 대외적 위상을 높일 목적으로 시행되기도 한다. 우리나라에서는 1953년의 제1차 통화조치에 따라 100원(圓)이 1환(圜)으로, 1962년의 제2차 통화조치에 따라 10환(圜)이 1원으로 변경된 사례가 있다. 리쇼어링/니어쇼어링/프렌드쇼어링리쇼어링(Reshoring)은 해외에 공장이나 생산기지를 둔 기업이 다시 본국으로 돌아오는 현상으로 인건비 등 생산비용 절감을 위하여 해외로 생산시설을 옮기는 오프쇼어링 (offshoring)과 반대되는 말이다. 리쇼어링 양상은 2008년 금융위기 이후 미국의 제조업 쇠퇴와 실업률 상승, 중국 의존도 증가, 사회·경제적 양극화 등을 배경으로 미국의 버락 오바마 대통령이 제조업 부활과 일자리 창출을 위하여 자국으로 돌아오는 기업에 각종혜택을 제공하면서 촉진되었다. 최근 각국 정부는 자국내 일자리 창출과 경제활성화를 위하여 리쇼어링을 추진하고 있다. 한편 니어쇼어링(Nearshoring)은 물류 효율성 제고와 생산비용 절감 등을 위하여 지리적으로 가까운 국가로, 프렌드쇼어링(Friend-Shoring) 은 지정학적 리스크 감소와 경제안보 강화 등을 위하여 정치적·외교적으로 우호적인 국가 로 업무나 생산활동을 이전하는 전략을 뜻한다.','','ㄹㄷㄴㅁㄴㅇㅅ',ARRAY['글로벌가치사슬(GVC)']::text[]),
(199,'리스크 온(Risk On)/오프(Off)','리스크 온(Risk On)과 리스크 오프(Risk Off)는 투자 심리를 나타내는 용어로서 시장의 위험 선호도와 위험 회피 심리를 반영한다.','리스크 온(Risk On)과 리스크 오프(Risk Off)는 투자 심리를 나타내는 용어로서 시장의 위험 선호도와 위험 회피 심리를 반영한다. 리스크 온은 투자자들이 위험 자산(주식, 암호화폐 등)에 적극적으로 투자하는 상황을 의미하고, 리스크 오프는 반대로 안전 자산(채권, 금 등)으로 투자 자금을 이동하는 상황을 의미한다. 리스크 온 상황에서는 경제 성장 기대감 증대, 금리 인상 가능성 감소, 기업 실적 호조 등의 요인이 작용하는 가운데 투자자들이 경제 상황에 대해 낙관적인 태도를 보이며 위험 자산에 대한 투자를 늘리는 경향을 보인다. 반대로 리스크 오프 상황에서는 경기침체 우려 증대, 금리 인상 가능성 증가, 지정학적 리스크 고조 등의 요인이 작용하는 가운데 투자자들이 경제 상황에 대해 비관적인태도를 보이며 안전 자산으로 자금을 이동시키는 경향을 보인다.','','ㄹㅅㅋㅇ()/ㅇㅍ()',ARRAY['위험 선호/회피','안전자산/위험자산']::text[]),
(200,'마샬의 k','마러라고 합의 마러라고 합의는 트럼프 미국 대통령의 플로리다 별장 ‘마러라고(Mar-a-Lago)’의 이름을 딴 경제 정책 구상으로 1985년의 플라자 합의를 현대적으로 재해석한 전략이다.','마러라고 합의 마러라고 합의는 트럼프 미국 대통령의 플로리다 별장 ‘마러라고(Mar-a-Lago)’의 이름을 딴 경제 정책 구상으로 1985년의 플라자 합의를 현대적으로 재해석한 전략이다. 이 정책 구상은 트럼프 2기 행정부가 시작되면서 경제자문위원장 스티븐 미런과 재무장관 스콧 베센트가 주도적으로 제안한 것으로 알려져 있다. 이 정책 구상의 목표는 미국의 무역적자 해소와 제조업 부흥이며 이를 위해 달러화의 인위적 평가절하를 추진해 미국 제품의 가격경쟁력을 높이고 수출을 촉진하는 것이 핵심이다. 무역 상대국들과의 합의를 통해 달러화 가치를 큰 폭 절하시키고, 미국의 안보 우산을 제공 받는 동맹국들에게 무역 협상에 서 더 많은 양보를 요구하며, 외국이 보유한 미국 국채를 초장기(예: 100년 만기) 저금리채권으로 교환하여 미국의 부채 부담을 줄이는 방안 등이 포함되어 있다. 이러한 정책 구상은 미국의 무역 및 재정 적자 부담을 동맹국에 전가하려는 의도가 크다는 비판을 받고 있다. 마샬의 k 마샬의 k(Marshallian k)는 경제 전체의 명목소득 대비 통화량 보유 비율을 의미한다. 어떤 경제에서 일정 기간 동안 명목국민소득이 PY이고 화폐의 유통속도가 V일 경우 실물거래를 위해 필요한 화폐의 양, 즉 화폐의 수요는 다음과 같이 구할 수 있다. 거래수량설방정식 MV=PY에 따르면 M=1/V×PY=kPY의 관계가 도출된다. 따라서 마샬의 k는 화폐유통속도의 역수와 동일한 값을 갖는 상수에 해당한다. 이 이론은 화폐의 유통속도가 일정함을 전제로 하고 있다. 그러나 화폐의 유통속도는 결제 수단의 발전 등 여러 가지 제도 적 요인에 영향을 받을 뿐만 아니라 단기적으로도 매우 변동이 심하게 나타난다. 경기가 호황일 때에는 유통속도가 빨라지고 불황일 때는 늦어지는 경기순응적 움직임을 보인다. 한편 마샬의 k는 MS=Md=kPY에 의거 한 나라의 경제규모 대비 통화공급의 적정 수준을 판단하는 지표로 사용되기도 한다. 그러나 현실적으로 통화량이 다양하게 정의(현금통화, M1, M2, Lf 등)될 뿐만 아니라 금융제도의 혁신 등으로 유통속도도 많이 변하기 때문에 마샬의 k의 적정 수준을 사전적으로 정하는 것은 매우 어려운 일이다.','','ㅁㅅㅇ','{}'::text[]),
(201,'마스트리히트조약','마스트리히트조약(Maastricht Treaty)은 유럽공동체(EC)의 12개 회원국(벨기에, 덴마크, 독일, 그리스, 스페인, 프랑스, 아일랜드, 룩셈부르크, 이탈리아, 네덜란드, 포르투갈…','마스트리히트조약(Maastricht Treaty)은 유럽공동체(EC)의 12개 회원국(벨기에, 덴마크, 독일, 그리스, 스페인, 프랑스, 아일랜드, 룩셈부르크, 이탈리아, 네덜란드, 포르투갈, 영국)이 1992년 2월 7일 네덜란드 마스트리히트에서 서명하고, 1993년 11월 1일부터 발효된 조약으로 정식 명칭은 유럽연합조약(Treaty on European Union)이다. 이 조약은 EC 가 시장 통합을 넘어 정치·경제적 통합체로 결합하는 토대가 되었으며, 유럽중앙은행 창설 및 단일통화 사용의 경제통화동맹(EMU) 달성, 공동방위정책 형성, 유럽연합 시민권제도 도입, 사법 및 치안에 관한 협력 등을 핵심내용으로 하고 있다. 이에 따라 유럽공동체 (EC)는 명칭을 유럽연합(EU)으로 변경하여 새롭게 출범하면서 단일통화를 단계적으로 도 입하기로 하였다. 아울러 유럽경찰 창설에 합의하고 회원국 간의 격차를 해소하기 위한 결속기금 조성을 추진하는 한편 유럽의회의 역할도 조사권, 청원권, 협력절차 도입을 통해 강화하였다.','','ㅁㅅㅌㄹㅎㅌㅈㅇ',ARRAY['유럽연합(EU)','유럽중앙은행(ECB)']::text[]),
(202,'마찰적 실업','때 증권사나 브로커가 추가 증거금(margin)을 요구하는 것을 말하는데, 이는 투자자가 레버리지(leverage)를 사용하여 거래할 때 발생할 수 있는 위험 중 하나다.','때 증권사나 브로커가 추가 증거금(margin)을 요구하는 것을 말하는데, 이는 투자자가 레버리지(leverage)를 사용하여 거래할 때 발생할 수 있는 위험 중 하나다. 마진 거래는 투자자가 자기자본 외에 증권사 등에서 돈을 빌려 투자하는 방식으로서 레버리지를 활용하여 적은 자본으로 큰 수익을 노릴 수 있지만 반대로 큰 손실을 볼 위험도 존재한다. 만일투자자가 빌린 돈으로 투자한 자산의 가치가 하락하여 증권사나 브로커가 정한 유지 증거금 수준 이하로 떨어지면 마진콜이 발생한다. 이때 투자자는 추가 증거금을 납입하거나 보유자산을 매도하여 손실을 줄여야 하는데 추가 증거금을 납입하지 못할 경우 증권사에 서 강제로 자산을 매도할 수도 있으며 이에 따라 투자자는 큰 손실을 볼 수 있다.','','ㅁㅊㅈㅅㅇ',ARRAY['실망실업자','자발적 실업']::text[]),
(203,'만기수익률','만기수익률(YTM; Yield to Maturity)은 채권을 만기까지 보유했을 때 얻을 수 있는 예상연간 수익률을 말한다.','만기수익률(YTM; Yield to Maturity)은 채권을 만기까지 보유했을 때 얻을 수 있는 예상연간 수익률을 말한다.','','ㅁㄱㅅㅇㄹ',ARRAY['이표채']::text[]),
(204,'매매보호 서비스(Escrow)','판매자와 구매자 사이의 신용관계가 불확실한 전자상거래 시 신뢰할 수 있는 중립적인 제 3자가 중개역할을 하여 상거래가 원활히 이루어질 수 있도록 하는 서비스를 말한다.','판매자와 구매자 사이의 신용관계가 불확실한 전자상거래 시 신뢰할 수 있는 중립적인 제 3자가 중개역할을 하여 상거래가 원활히 이루어질 수 있도록 하는 서비스를 말한다. 구체적으로는 전자상거래 시 소비자가 물품을 구매한 후 대금을 제3자에게 보관하고, 판매자는 제3자에게 입금 사실을 확인하고 구매자에게 물품을 발송한다. 구매자는 물품 확인 후제3자에게 물품의 도착 및 구매 여부를 알리고, 제3자는 판매자에게 대금을 송금하는 절차로 이루어진다. 중개하는 제3자는 수수료를 수익으로 얻는다. 에스크로(Escrow) 서비스는 구매자의 인터넷 사기 피해나 판매자의 채권추심 비용 등 전자상거래 피해를 줄여주는 효과가 있다.','','ㅁㅁㅂㅎㅅㅂㅅ()','{}'::text[]),
(205,'매몰비용','이미 지급되어 회수할 수 없는 비용을 말한다.','이미 지급되어 회수할 수 없는 비용을 말한다. 기회비용은 어떤 것을 선택할 때 포기하여야 하는 비용을 말하지만, 매몰비용(Sunk Cost)은 무엇을 선택하는가에 상관없이 지급할수밖에 없는 비용이다. 이미 지급된 매몰비용에 대해서는 더 이상 아무것도 할 수 없고 이 로 인해 현재 시점에서 아무것도 포기할 필요가 없기 때문에 매몰비용과 관련된 기회비용은 영(0)이다. 따라서 어떤 선택을 할 때에는 선택에 따른 편익은 극대화하고 비용은 최소화하되 이미 지출된 매몰비용은 무시해야 한다. 의사결정을 할 때 매몰비용에 집착하면의사결정을 제대로 할 수 없게 되는데, 이미 투입한 비용과 노력이 아까워 경제성이 없는 프로젝트를 중단하지 않고 지속함으로써 결국 손실을 키우는 경우를 매몰비용 오류(Sunk Cost Fallacy)라고 한다.','','ㅁㅁㅂㅇ',ARRAY['기회비용']::text[]),
(206,'매입외환/환가료','매입외환은 외국환은행이 고객으로부터 매입한 수출환어음, 내국신용장어음, 외화수표, 약속어음 등의 외국환으로 표시된 자산을 말한다.','매입외환은 외국환은행이 고객으로부터 매입한 수출환어음, 내국신용장어음, 외화수표, 약속어음 등의 외국환으로 표시된 자산을 말한다. 외국환은행이 수출환어음 등의 외국환을 매입하면 원화 대금은 즉시 고객에게 지급되나 외화 자금은 추심 후 외국환은행에게입금된다. 따라서 원화 자금 지급일로부터 외화 자금 입금일까지 은행이 고객에게 자금을 대출해주는 효과가 발생한다. 이와 같이 외국환은행이 고객으로부터 수출환어음 등을 매입하는 경우, 고객에게 원화 대금을 지급한 시점과 어음 등의 발행자로부터 외화자금을 받는 시점 사이에 은행이 부담하는 어음금액에 대한 이자와 환차손 등을 보전받기 위해고객에게 수수료를 부과하는데 이를 환가료라고 한다. 따라서 환가료가 징수되는 거래는 은행이 고객으로부터 어음 등을 매입한 후 그 대금을 외화자금으로 수취하는 거래이다. 만약 원화로 대금을 수취할 경우에는 원/달러 환율 등이 적용되고 이 환율에 수수료가 포함되기 때문에 환가료를 따로 징수하지 않는 것이 일반적이다.','','ㅁㅇㅇㅎ/ㅎㄱㄹ',ARRAY['내국신용장']::text[]),
(207,'매출액영업이익률','기업의 주된 영업활동의 효율성을 측정하는 지표로 제조 및 판매활동에 의해 창출된 영업손익을 매출액으로 나누어 산출한다.','기업의 주된 영업활동의 효율성을 측정하는 지표로 제조 및 판매활동에 의해 창출된 영업손익을 매출액으로 나누어 산출한다. 매출액영업이익률은 다시 생산효율성(매출총손익/ 매출액)과 관리효율성(영업손익/매출총손익)으로 분리하여 이의 변동요인을 찾아낼 수도 있다. 매출액영업이익률은 정상적인 경우 높을수록 좋으나 어떠한 표준치가 있을 수 없으므로 경쟁관계에 있는 기업이나 동종 업종의 평균치 또는 그 기업의 과거실적과 비교해서 좋고 나쁨을 판단하게 된다. 영업손익 매출총손익* 영업손익* 매출액영업이익률 = ×100 = ( × )×100 매출액 매출액 매출총손익 * 매출총소익 = 매출액 - 매출원가 ** 영업손익 = 매출총손익 - 판매비와 관리비','','ㅁㅊㅇㅇㅇㅇㅇㄹ','{}'::text[]),
(208,'머니마켓펀드(MMF)','머니마켓펀드(MMF; Money Market Fund)는 고객의 일시적인 여유자금을 금리위험과 신용위험이 적은 국공채, 어음 등에 운용하고 동 운용에서 발생하는 수익을 배당하는 펀드의 일종으로서…','머니마켓펀드(MMF; Money Market Fund)는 고객의 일시적인 여유자금을 금리위험과 신용위험이 적은 국공채, 어음 등에 운용하고 동 운용에서 발생하는 수익을 배당하는 펀드의 일종으로서 대표적인 단기금융상품이다. MMF로 들어온 자금은 주로 부도 위험이 거의 없는 국채, 통화안정증권 등의 채권, 우량 CP, CD 및 예금 등으로 운용하며 운용자산의 가중평균 잔존만기가 60일(시가평가의 경우는 120일) 이내로 제한된다. 편입자산의 신용등급은 취득시점을 기준으로 상위 2개 등급 이내(채권 AA이상, CP A2 이상)여야 하며 주식과 관련이 있는 채권(전환사채 등)이나 사모발행채권 등은 운용대상 자산에서 제외된다. 2022년 4월부터 법인형 MMF에 대해 시가평가제도가 도입되었으나 안정적 자산의 비중이 30%를 초과하는 MMF의 경우 기존과 같이 장부가 평가가 허용된다. 이에 따라현재 대부분의 MMF는 안정성을 추구하는 투자자의 선호를 반영하여 장부가 평가를 적용받기 위한 운용행태를 나타내고 있다. MMF는 유동성 측면에서 익일 설정 및 익일 환매가 이루어짐에 따라 다른 펀드에 비해 유동성이 높은 편이며 자산의 운용은 자산운용사가, 판매는 은행 및 증권사가 하고 있다.','','ㅁㄴㅁㅋㅍㄷ()',ARRAY['단기금융시장','채권시가평가','펀드']::text[]),
(209,'명목GDP목표제','명목GDP목표제란 명목GDP가 사전에 정한 목표수준을 따라가는 것을 목표로 하는 통화정책 운영체제이다.','명목GDP목표제란 명목GDP가 사전에 정한 목표수준을 따라가는 것을 목표로 하는 통화정책 운영체제이다. 이는 글로벌 금융위기 이후 저인플레이션, 저성장, 저금리 현상이 지속됨에 따라 물가안정목표제의 대안으로 일부 학계를 중심으로 제시된 방안이다. 명목 GDP목표제에서는 물가와 실물경제에 동일한 가중치를 부여하기 때문에 경기부진에 보다 적극적으로 대응하는 것이 가능하다. 또한 유가급등과 같은 공급충격으로 물가상승과 생산감소가 동시에 발생하는 경우 어느 정도의 물가상승을 허용하여 생산감소폭을 축소시키는 유연한 정책대응이 가능하다는 장점도 있다. 그러나 명목GDP목표제의 경우 물가 안정에 대한 중앙은행의 신뢰성을 확보하기 어렵고 현실 적합성이 크게 떨어진다는 단점이 있다. 물가와 경기를 동시에 고려하기 때문에 명목기준지표로서의 명료성이 떨어지고 기대 인플레이션을 안정적으로 관리하기가 어렵다. 또한 목표대상지표의 포괄범위도 넓어명목금리/실질금리중앙은행의 통제가능성도 낮다. 이러한 한계로 현재 명목GDP목표제를 실제로 채택한 사례는 아직 없는 상황이다.','','ㅁㅁㅁㅍㅈ',ARRAY['물가안정목표제','제로금리정책','양적완화정책']::text[]),
(210,'명목국내총생산/실질국내총생산','명목국내총생산(Nominal GDP)은 한 나라 안에서 생산된 최종생산물의 가치를 그 생산물이 생산된 기간의 가격을 적용하여 계산한 것이다.','명목국내총생산(Nominal GDP)은 한 나라 안에서 생산된 최종생산물의 가치를 그 생산물이 생산된 기간의 가격을 적용하여 계산한 것이다. 명목GDP의 변동분에는 최종생산물의 수량과 가격변동분이 혼재되어 있다. 명목GDP는 경제규모 등의 파악에 이용된다. 반 ㅁ 면 실질국내총생산(Real GDP)은 한 나라 안에서 생산된 최종생산물의 가치를 기준년도 의 가격으로 측정한 것이다. 실질GDP는 우리나라를 비롯한 많은 국가에서 UN이 권고한 국제기준인 국민계정체계(SNA; System of National Accounts)에 따라 연쇄가중법에 의 해 추계되고 있다. 연쇄가중법은 기준연도의 가중치를 계속 적용하지 않고 기준연도의 명목금액에 연쇄물량지수를 곱하여 실질GDP를 산출한다. 실질GDP는 경제성장, 경기변동등 전반적인 경제활동의 흐름을 분석하는 데 이용된다. 명목GDP는 특정 시점의 국가간비교, 다른 지표의 기준치(예: 총저축률, GDP대비 경상수지 비율 등)로 활용된다.','','ㅁㅁㄱㄴㅊㅅㅅ/ㅅㅈㄱㄴㅊㅅㅅ',ARRAY['연쇄가중법','계절변동조정시계열','경제성장률']::text[]),
(211,'명목금리/실질금리','금리는 돈의 가치 즉, 물가변동을 고려하느냐의 여부를 기준으로 명목금리와 실질금리로 구분할 수 있다.','금리는 돈의 가치 즉, 물가변동을 고려하느냐의 여부를 기준으로 명목금리와 실질금리로 구분할 수 있다. 명목금리는 돈의 가치 변동을 고려하지 않고 외부로 표현된 표면상의 금리를 말한다. 이와 달리 실질금리는 물가상승률을 고려한 금리를 의미한다. 예컨대 금년중 1년 만기 정기예금의 명목금리가 3%이고 물가상승률이 1%일 경우 명목금리는 3%이 지만 실질금리는 2%(=3%-1%)가 된다. 한편, 금리와 물가의 관계를 설명하는 피셔효과 (Fisher effect)란 금융거래시 명목금리는 실질금리에 예상 물가상승률을 더해서 결정되는 것을 말한다. 예를 들어 시장참가자들이 미래의 인플레이션율을 합리적으로 예상하여실질금리에 덧붙이는 형태로 금리를 결정한다면 실질금리는 변하지 않고 명목금리만 조정될 수 있는 것이다. 그러나 경험적으로 1970~80년대 두 자릿수의 인플레이션 시대에 명목금리에서 물가상승률을 차감한 사후적(ex post) 실질금리가 마이너스로 나타나는 사례도 있어 장기적으로 실질금리가 불변한다는 견해에 대해서는 논란이 있다.','','ㅁㅁㄱㄹ/ㅅㅈㄱㄹ',ARRAY['피셔효과']::text[]),
(212,'명목소득/실질소득','명목소득(Nominal Income)은 대상 경제주체의 소득이 발생할 당시의 가격으로 측정된 소득을 말하며, 실질소득(Real Income)은 통화가치의 변동을 감안하여 명목소득을 기준시점에 맞춰…','명목소득(Nominal Income)은 대상 경제주체의 소득이 발생할 당시의 가격으로 측정된 소득을 말하며, 실질소득(Real Income)은 통화가치의 변동을 감안하여 명목소득을 기준시점에 맞춰 조정한 것을 말한다. 예를 들어 2015년에 A씨의 연간 소득을 당시 통화가 치로 측정한 금액이 3,000만원 이라면 명목소득은 3,000만원에 해당한다. 2017년 측정된 A씨의 명목소득이 3,500만원이라면, 2년 동안 A씨의 명목소득은 500만원 증가한 셈이다. 이 경우 A씨의 경제형편이 나아졌는지를 판단하기 위해서는 보다 정확한 정보를 반영하고 있는 실질소득의 변화 여부를 확인해 보아야 한다. 만약 2015~2017년중 인플레이션율(물가상승률)이 15%라면 같은 기간중 통화가치는 15% 하락한 것으로 볼 수 있다. 이 경우 A씨의 2017년 명목소득 3,500만원은 실질소득 기준으로 3,043만원(3500/ (1+0.15))이 된다. 따라서 2015~2017년중 통화가치 변동을 감안할 경우 A씨의 실질소득은 43만원 증가한 것이 된다. 통화의 가치는 인플레이션 등으로 인해 시간이 지날수록 하락하므로 수시로 발표되는 다양한 경제지표를 정확하게 이해하기 위해서는 명목 (nominal)과 실질(real)의 개념으로 구분해서 살펴보아야 한다. 국내총생산에 대한 명목 GDP·실질GDP, 임금에 대한 명목임금·실질임금, 이자율에 대한 명목이자율·실질이자율등은 명목지표와 실질지표를 구분하는 한 예라 하겠다.','','ㅁㅁㅅㄷ/ㅅㅈㅅㄷ',ARRAY['실질임금']::text[]),
(213,'모기지대출','모기지대출(Mortgage Loan)은 주택이나 부동산을 담보로 하여 은행 등 금융기관에서 장기간 자금을 빌리는 대출을 말한다.','모기지대출(Mortgage Loan)은 주택이나 부동산을 담보로 하여 은행 등 금융기관에서 장기간 자금을 빌리는 대출을 말한다.','','ㅁㄱㅈㄷㅊ',ARRAY['주택저당증권(MBS)','자산유동화']::text[]),
(214,'모바일뱅킹','모바일뱅킹 서비스는 고객이 휴대전화 등 모바일기기를 이용하여 무선인터넷을 통하여금융기관에 접속하여 이용할 수 있는 금융서비스이다.','모바일뱅킹 서비스는 고객이 휴대전화 등 모바일기기를 이용하여 무선인터넷을 통하여금융기관에 접속하여 이용할 수 있는 금융서비스이다. 이 서비스는 은행이 이동통신회사의 무선인터넷망을 통해 고객의 자금이체 및 계좌조회 등 금융거래과정 전반을 관리하는 것을 기본구조로 하고 있다. 1999년 농협은행 등이 제공하기 시작한 국내 모바일뱅킹 서 비스는 2009년 스마트폰 기반 모바일뱅킹 서비스가 개시된 이후에는 주로 스마트폰을 통해 제공되고 있다. 모바일뱅킹을 통해 제공되고 있는 서비스에는 예금조회, 거래명세조회, 자금이체 등이 있으며, 일부 은행에서는 현금서비스, 대출, 환율조회, 수표조회, 사고 신고 등의 서비스까지 제공하고 있다. 모바일뱅킹 서비스는 대부분의 국내은행 및 우체 ㅁ 국, 신용협동조합 및 새마을금고중앙회 등에서 제공되고 있다.','','ㅁㅂㅇㅂㅋ',ARRAY['간접금융/직접금융']::text[]),
(215,'무디스','무디스는 1909년 미국의 출판업자인 John Moody가 창업한 신용평가기관이다.','무디스는 1909년 미국의 출판업자인 John Moody가 창업한 신용평가기관이다. 1929년세계 대공황 때 무디스가 ‘투자적격’으로 평가한 기업들이 채무를 100% 이행하게 되면서 높은 신뢰와 명성을 획득한 이후 세계적인 투자 자문회사로 성장하였으며 S&P, Fitch와 함께 세계 3대 국제신용평가기관으로 인정받고 있다. 무디스는 일반적으로 채권의 신용등급을 신용리스크 수준에 따라 Aaa(최우량), Aa, A, Baa, Ba, B, Caa, Ca, C(최저)의 순으로 매기며, Aa에서 Caa까지는 숫자 1, 2, 3을 추가하여 등급을 세분한다. 무디스의 평가원칙은 정량분석(quantitative)을 강조하고 있으며, 여타 두 신용평가기관에 비해 평가 경향이 보수적인 것으로 알려져 있다. 주요 평가항목은 공채와 우선주식, 정부의 부채 상환 능력, 장단기 채무 이행 능력, 은행감독 정도, 자본시장 구조, 재무상의 투명성 및 규제환경, 채무 감당 능력, 유동성 등 시장리스크, 기업의 재정 및 리스크 경영과 통제 등이다.','','ㅁㄷㅅ',ARRAY['스탠더드&푸어스']::text[]),
(216,'무역지수','일반적으로 거래금액의 변동은 가격이 변하거나 물량이 변하거나 또는 가격과 물량이 동시에 변하기 때문에 나타난다.','일반적으로 거래금액의 변동은 가격이 변하거나 물량이 변하거나 또는 가격과 물량이 동시에 변하기 때문에 나타난다. 무역지수는 경제성장, 고용 등과 밀접한 관계를 갖고 있는 수출액 또는 수입액의 변동요인을 가격요인과 물량요인으로 나누어 분석하기 위해 한국은행에서 작성하고 있다. 무역지수에는 수출입금액지수, 수출입물가지수, 수출입물량지수가 있다. 이러한 무역지수통계를 이용하여 한 나라의 교역조건을 측정한다. 수출입금액지수는 수출입 품목의 비교시점 수출입금액을 기준시점 수출입금액으로 나눈 후 100을 곱하여 산출한다. 수출입물량지수는 먼저 계산한 수출입금액지수를 수출입물가지수로 나 눈 후 100을 곱하여 산출하는데, 이때 수출입물가지수는 수출입 계약과 통관 간의 시차를 조정하여 이용한다. 예를 들어 승용차 수출의 경우 계약부터 실제 통관까지 평균 2개월이 소요된다면 무역지수 작성에 적용되는 자동차 수출물가지수는 2개월 전의 자동차의 수출물가지수가 된다.','','ㅁㅇㅈㅅ',ARRAY['순상품교역조건지수','수출입물량지수']::text[]),
(217,'무위험지표금리(KOFR)','무위험지표금리(KOFR)는 Korea Overnight Financing Repo Rate의 약자로서, 국채· 통안증권을 담보로 하는 익일물 RP금리를 사용하여 산출한 우리나라의 무위험지표금리…','무위험지표금리(KOFR)는 Korea Overnight Financing Repo Rate의 약자로서, 국채· 통안증권을 담보로 하는 익일물 RP금리를 사용하여 산출한 우리나라의 무위험지표금리 (RFR; Risk-Free Reference Rate)이다. 이는 투자자가 신용 리스크 없이 얻을 수 있는 이론상의 최소 수익률을 나타내는 금리로서 LIBOR 금리 조작사건 등 기존 금융거래지표의 신뢰도 하락을 계기로 개발된 대체지표금리이다. KOFR는 국채·통안증권을 담보로 하는 초단기 거래이기 때문에 무위험 금리에 가깝고, 실거래에 기반하여 산출되기 때문에 조작 가능성이 없는 것이 특징이다. 우리나라는 2021년 2월 RFR로 RP거래금리를 최종선정했으며, 증권결제 및 장외 RP거래 환매서비스를 제공하는 기관인 한국예탁결제원이 중요지표 산출기관으로 최종 선정되어 KOFR의 산출·공시 업무를 수행하고 있다. 한국무위험지표금리(KOFR)는 2021년 11월 26일부터 「금융거래지표의 관리에 관한 법률」에 따른 중요지표로서 정식 공시를 시작하였으며, KOFR Index는 2018년 1월 2일을 기준시점으로 1,000을 기준지수로 하여 산출된다. KOFR는 신뢰할 수 있는 지표금리 제공을 통해 금융시장의 안정성을 높이며, 국제적인 금리 기준과의 정합성을 높여 국내 금융시장의 국제화를 촉진한다. 또한, 시장에서 실제로 거래된 금리를 기반으로 산출함으로써 금리 산정의 투명성을 높이는 KOFR는 국내 금융시장에서 중요한 역할을 수행하며, 앞으로 더욱 다양한 분야에서 활용될 것으로 기대된다.','','ㅁㅇㅎㅈㅍㄱㄹ()',ARRAY['지표금리','환매조건부채권(RP)']::text[]),
(218,'물가안정목표제','물가안정목표제(Inflation Targeting)란 중앙은행이 명시적인 중간목표(intermediate target) 없이 일정기간 동안 또는 중장기적으로 달성해야 할 물가상승률 목표치를 미리…','물가안정목표제(Inflation Targeting)란 중앙은행이 명시적인 중간목표(intermediate target) 없이 일정기간 동안 또는 중장기적으로 달성해야 할 물가상승률 목표치를 미리 제시하고 이에 맞추어 통화정책을 운영하는 방식이다. 즉, 중앙은행은 통화량, 금리, 환율등 다양한 정보변수를 활용하여 장래의 인플레이션을 예측하고 실제 물가상승률이 목표치에 수렴할 수 있도록 통화정책을 운영하며, 이후 그 성과를 평가하고 시장의 기대와 반응을 반영하면서 정책방향을 수정해 나간다. 물가안정목표제는 다음과 같은 핵심 요소를 포함한다. 첫째로 물가안정목표의 구체적인 수치가 제시되어야 하고, 둘째로 통화정책의 목표 중에서 물가안정이 가장 중요한 목표가 되어야 하며, 셋째로 제시된 목표의 달성에 대한 책임성이 확보되어야 한다는 점이다. 물가안정목표제는 1990년 뉴질랜드에서 처음 도입되었으며, 이후 캐나다, 영국, 스웨덴, 호주 등 선진국과 다수의 신흥시장국으로 확산되었다. 우리나라는 1998년부터 물가안정목표제를 도입하여 시행하고 있다.','','ㅁㄱㅇㅈㅁㅍㅈ',ARRAY['통화정책 운영체제(monetary policy regime)']::text[]),
(219,'물가지수','시장에서 거래되는 여러 가지 상품과 서비스의 가격을 경제생활에서 차지하는 중요도를 고려하여 평균한 종합적인 가격 수준을 물가라고 한다.','시장에서 거래되는 여러 가지 상품과 서비스의 가격을 경제생활에서 차지하는 중요도를 고려하여 평균한 종합적인 가격 수준을 물가라고 한다. 물가지수는 물가의 변화를 한 눈에 알아볼 수 있도록 기준연도의 물가수준을 100으로 놓고 비교되는 다른 시점의 물가를 지수의 형태로 나타낸 것을 말한다. 물가지수(PI; Price Index)는 경제성장, 국제수지 등 과 함께 한 나라 거시경제의 움직임을 나타내는 중요한 경제지표이다. 물가지수를 이용하면 일정기간 동안의 생계비 또는 화폐가치의 변화를 측정할 수 있고 명목금액으로부터 실질금액을 산출할 수 있다. 또한 물가수준을 통해 경기변동에 대해 어느 정도 가늠할 수 있다. 물가는 경제 전체의 총공급과 총수요의 영향을 받아 변동한다. 총수요에 영향을 끼치는 대표적인 요인으로는 통화량과 가계소득을 들 수 있다. 반면, 임금 및 국제원자재가격등 생산요소 가격은 총공급을 변화시키는 요인이다. 기대인플레이션은 총수요와 총공급모두에 영향을 준다. 우리나라의 대표적인 물가지수로 생산자물가지수, 소비자물가지수, 수출입물가지수, 농가판매 및 구매가격지수 등을 들 수 있다.','','ㅁㄱㅈㅅ',ARRAY['국내공급물가지수','근원인플레이션']::text[]),
(220,'뮤추얼펀드','투자자들이 자금을 모아 투자 회사를 설립해 주식이나 채권, 파생상품 등에 투자한 후그 운용수익을 투자자, 즉 주주들에게 배당금의 형태로 나누어주는 투자신탁의 하나이 다.','투자자들이 자금을 모아 투자 회사를 설립해 주식이나 채권, 파생상품 등에 투자한 후그 운용수익을 투자자, 즉 주주들에게 배당금의 형태로 나누어주는 투자신탁의 하나이 다. 뮤추얼펀드는 투자자가 유가증권을 직접 매매하는 것이 아니라 전문 펀드매니저를 통해 운용하는 간접투자 방식이다. 제도적으로 회사형과 계약형으로 나눌 수 있고, 주요 투자대상에 따라 단기금융시장, 채권형(또는 고정수입), 주식형(또는 순자산), 혼합형','','ㅁㅊㅇㅍㄷ','{}'::text[]),
(221,'미달러화지수','(하이브리드) 등으로 분류된다.','(하이브리드) 등으로 분류된다. 미국의 경우 뮤추얼펀드 이전의 간접투자 제도로는 1868 년 투자조합 형태로 설립된 Foreign Colonial Government Trust가 최초이고 1924년신탁형태로 보스톤에 설립된 Massachusetts Investors Trust가 있었다. 1940년 투자회사법(Investment Company Act 1940)의 제정으로 법적 기반이 정비되었다. 한편 단기금융시장에 투자하는 MMMF(Money Market Mutual Funds)는 지난 1970년대 금리가 규제되고 있던 시대에 혁신적인 금융상품의 하나로 발전하면서 미국 금융시장에서 금리규제 철폐와 금융자유화를 가속화하는 데 중요한 역할을 한 대표적인 금융혁신 상품으로 평가된다. 우리나라는 1998년 9월 증권투자회사법이 제정되어 국제적 형태의 뮤추얼펀드가 도입되었고, 자본시장법에 따라 집합투자기구와 집합투자증권이란 명칭으로 규정되어 있다.','','ㅁㄷㄹㅎㅈㅅ',ARRAY['브레튼우즈체제']::text[]),
(222,'미달러화페그제도','페그제도란 자국통화를 단일 외국통화나 복수의 통화바스켓에 연동시켜 고정환율을 유지하는 제도이다.','페그제도란 자국통화를 단일 외국통화나 복수의 통화바스켓에 연동시켜 고정환율을 유지하는 제도이다. 따라서 미달러화페그제도는 자국 통화의 미국 달러화에 대한 환율은 고 정시켜 둔 채 자국 통화의 기타 통화에 대한 환율은 미국 달러화 대 기타통화의 환율 변동에 따라 자동으로 결정되게 하는 환율제도를 말한다. 통상 외환 당국은 직접 및 간접 개입을 통해서 자국통화의 미달러화에 대한 시장환율이 기준환율을 중심으로 좁은 범위(± 1% 이내, ± 2% 이내 등)에서 변동하도록 관리한다. 페그제도를 채택하면 환율변동에 대한 불확실성이 제거됨으로써 국경 간 교역 및 자본유출입의 원활화를 도모하는 데 유리하지만, 미국 달러화의 가치변동에 따라 자국 통화의 가치가 수동적으로 변동하게 됨으로써통화의 가치가 자국의 경제 상황 또는 수출경쟁력을 적절히 반영되지 못하는 문제점이 발생할 수 있다.','','ㅁㄷㄹㅎㅍㄱㅈㄷ',ARRAY['고정환율제도/자유변동환율제도','복수통화바스켓제도']::text[]),
(223,'미발행화폐','미발행화폐란 한국은행이 보유하고 있는 은행권과 주화 중 사용하기에 적합하지 아니하여 폐기(잘게 썰거나, 분쇄 또는 녹이는 등의 방법으로 소각)하기로 결정한 화폐를 제외한 모든 은행권과 주화를…','미발행화폐란 한국은행이 보유하고 있는 은행권과 주화 중 사용하기에 적합하지 아니하여 폐기(잘게 썰거나, 분쇄 또는 녹이는 등의 방법으로 소각)하기로 결정한 화폐를 제외한 모든 은행권과 주화를 말한다. 한국은행은 미발행화폐를 필요한 곳에 적기에 공급하기 위하여 한국은행 본부와 각 지역본부에 분산하여 보관하고 있으며 동 화폐의 대부분은 한국조폐공사로부터 제조하여 납품받은 새화폐와 금융기관들이 지급준비금 불입 등을 위해입금한 화폐가 대부분이다. 그리고 한국은행은 미발행화폐를 한국은행 본부 또는 지역본부가 아닌 특정 금융기관에 보관케하는 미발행화폐 임치제도를 운용할 수 있다. 이는 한 국은행 본부 및 지역본부로부터 원격지에 위치하여 교통여건이 열악한 지역의 화폐수급애로를 해소하기 위하여 동 지역소재 금융기관 1개 점포를 지정하여 한국은행의 미발행화폐를 보관케하고 한국은행의 입회, 지시, 감독하에 화폐의 입·출업무를 수행하게 하는 제도이다. 이 제도는 1996년 가장 많은 23개 점포를 지정·운영하였으나 현재는 교통여건개선 등으로 한 곳도 운용하지 않고 있다.','','ㅁㅂㅎㅎㅍ','{}'::text[]),
(224,'미분양주택','주택사업자가 분양 공고를 내고 입주자를 모집하였으나 정해진 일정 내에 청약이 이루어지지 않은 주택이다.','주택사업자가 분양 공고를 내고 입주자를 모집하였으나 정해진 일정 내에 청약이 이루어지지 않은 주택이다. 미분양주택은 주택경기를 파악할 수 있는 지표 중 하나이다. 주택수요는 탄력적이지만 주택공급은 비교적 비탄력적이기 때문에 주택시장에서는 침체와 회복이 반복되는 경기순환적 특성을 보이며, 미분양주택은 이러한 경기순환 상황을 나타낸다. 주택공급이 과도하거나 금융위기와 같은 수요충격이 발생한 경우 미분양주택이 적체된 다. 이후 가격이 조정되는 과정 등을 거쳐 미분양주택이 소진되고 주택시장은 회복국면에 들어서게 된다. 우리나라에서는 선분양 제도를 통하여 주택이 지어지기 전 청약을 시행하는데 주택이 준공된 이후에도 분양계약이 체결되지 않는 경우 준공 후 미분양주택으로 분류하며, 준공 후 미분양주택이 지속적으로 적체되는 경우 해당 지역의 주택시장 침체가 더욱 심화되었음을 시사한다. 미분양주택 관련 정보는 국토교통부 통계누리, 통계청 국가 통계포털 등에서 살펴볼 수 있다.','','ㅁㅂㅇㅈㅌ',ARRAY['주택경기','주택청약','준공 후 미분양주택']::text[]),
(225,'바젤은행감독위원회/ 바젤위원회(BCBS)','1974년 독일 헤르슈타트 은행(Bankhaus Herstatt)의 도산이 국제외환시장 및 은행시스템에 심각한 영향을 미치면서 글로벌 은행감독기준 마련을 위한 공조의 필요성이 대두되었다.','1974년 독일 헤르슈타트 은행(Bankhaus Herstatt)의 도산이 국제외환시장 및 은행시스템에 심각한 영향을 미치면서 글로벌 은행감독기준 마련을 위한 공조의 필요성이 대두되었다. 그 결과 1974년말 G10 국가 중앙은행 총재회의의 결의로 바젤은행감독위원회','','ㅂㅈㅇㅎㄱㄷㅇㅇㅎ/ㅂㅈㅇㅇㅎ()','{}'::text[]),
(226,'반대매매','(BCBS; Basel Committee on Banking Supervision)가 설립되었다.','(BCBS; Basel Committee on Banking Supervision)가 설립되었다. BCBS는 은행 건전성을 규율하기 위한 국제기준 등을 제정하고 은행감독 관련 사안들에 대한 국제협력의 장을 제공해 왔다. 글로벌 금융위기 이후 BCBS가 은행 규제체계 개혁을 추진하는 과정에서 G10 이외 국가에 문호를 개방하면서 은행 규제·감독 관련 국제기준 제정기구로서의 중요 성은 더욱 커지게 되었다. 2024년 5월 14일 현재 G20 국가를 포함한 28개국(EU 포함)의 45개 중앙은행 및 은행감독기관이 회원으로, 非회원국 중앙은행, 감독기관 협의체, 국제기구 등 9개 기관이 초청기관 자격으로 참여하고 있다. 우리나라는 2009년 3월 한국은행과 금융감독원이 BCBS에 가입하였다. 반대매매반대매매(Reverse Trading)란 만기까지 대출금을 갚지 못하거나 담보가치가 일정 비율이하로 떨어지면 증권사가 주식을 강제로 처분하는 것을 의미한다. 신용매매(보유 주식을 담보로 하여 증권사 자금으로 거래), 스탁론 서비스(외상으로 주식 매수), 미수 거래(담보없는 위탁매매) 계좌를 이용해 주식을 매입했을 경우 주가하락에 따른 담보비율 하락으로 반대매매가 쏟아질 수 있다. 통상 미수거래의 경우에는 3일, 신용거래의 경우에는 1달~3 달이 상환기한이며 이 기간 안에 반대매매를 통해 상환하지 않는 경우나 담보가치가 일정 비율 이하로 하락할 때는 증권사에서 임의적으로 반대매매를 실시한다. 반대매매는 전날 종가 대비 20~30% 낮은 금액으로 주문이 산정되기 때문에 주가에 악영향을 미친다. 특히 개인투자자 지분율이 높은 코스닥시장 종목에 미치는 영향이 크다. 반대매매의 종류에는 크게 세 가지가 있다. 먼저 개장과 동시에 이뤄지는 반대매매다. 증권사로부터 돈을 빌린 신용융자, 예탁증권담보대출의 담보비율이 일정 수준 이하로 내려갔을 때 발생한 다. 둘째, 증권사로부터 돈을 빌려 주식을 사고 2거래일 뒤에 상환하는 미수거래도 만기안에 갚지 못할 경우 장 시작 전 동시호가 때 반대매매로 처분된다. 신용융자와 예탁증권담보대출의 담보비율은 증권사와 종목마다 다르지만 통상 140% 안팎 수준이다. 예를 들어 자기자금 1억원과 대출금 1억원을 합친 2억원으로 주식을 매입할 경우 대출금 1억원의 140%인 1억4000만원 상당의 주식을 갖고 있어야 한다. 주식의 가치가 그 밑으로 떨어지면 증권사가 추가 증거금을 요구한다. 담보부족이 발생하','','ㅂㄷㅁㅁ',ARRAY['신용거래','담보비율']::text[]),
(227,'발행시장','발행시장(Primary Market)이란 주식이나 채권 등의 유가증권을 신규로 발행하는 시장을 말한다.','발행시장(Primary Market)이란 주식이나 채권 등의 유가증권을 신규로 발행하는 시장을 말한다. 발행시장 내에서는 자금을 필요로 하는 기업, 금융기관, 정부, 지방공공단체 등 (발행주체)이 유가증권을 최초로 발행하여 자금공급자인 가계나 기관투자가 등(투자주체) 에게 제공하고 소정의 자금을 조달하는 일련의 과정이 발생한다. 발행시장 참여자에는 이 러한 발행주체와 투자주체 외에 인수기관이 있다. 인수기관은 발행주체를 대신하여 증권발행에 수반되는 사무 절차를 처리하고 유가증권 인수업무 등을 수행한다. 이중 채권 발행은 정부, 지방공공단체, 기업, 금융기관 등이 필요 자금을 조달하기 위해 일정한 이자를 지급할 것을 약속하며 발행하는 유가증권으로, 국채, 지방채, 회사채 등 다양한 종류가 있다. 발행시장에서 채권이 신규로 발행되어 투자자에게 판매되며, 이를 통해 발행주체는 장기 자금을 확보한다. 한편 이중 주식 발행은 기업공개, 유상증자, 무상증자 및 주식배당등의 형태로 이루어진다. 기업공개란 주식회사가 신규발행 주식을 다수의 투자자로부터모집을 하거나 이미 발행되어 대주주 등이 소유하고 있는 주식(구주)을 매출하여 주식을 분산시키는 것을 말하며, 유상증자는 기업재무구조 개선 등을 목적으로 회사가 신주를 발행하여 자본금을 증가시키는 것이다. 무상증자란 주금의 납입 없이 이사회의 결의로 준비금 또는 자산재평가적립금을 자본에 전입하고 전입액만큼 발행한 신주를 기존 주주에게발행중지화폐/유통정지화폐소유 주식수에 비례하여 무상으로 교부하는 것을 말하며, 주식배당이란 현금 대신 주식으로 배당함으로써 이익을 자본으로 전입하는 것을 말한다.','','ㅂㅎㅅㅈ',ARRAY['유통시장']::text[]),
(228,'발행어음','발행어음은 금융회사가 투자자로부터 자금을 조달하기 위해 고객을 수취인, 금융회사를 지급인으로 하여 어음을 의미하며 만기는 1년 이내이다.','발행어음은 금융회사가 투자자로부터 자금을 조달하기 위해 고객을 수취인, 금융회사를 지급인으로 하여 어음을 의미하며 만기는 1년 이내이다. 발행어음을 매입한 고객은 만기에 약정된 이자를 원금과 함께 받게 된다. 발행어음은 만기 구조에 따라 수시형과 만기형으로 구분할 수 있다. 수시형 발행어음은 입출금이 자유로우며 이자는 매일 계산하는 반면 만기형 발행어음을 만기가 정해져 있으며 중도에 해지하게 되면 만기이자율보다 낮은 이자율을 받게 된다. 한편 발행어음에는 만기가 도래하더라도 발행회사가 원금과 이자를 지급하지 못하는 신용위험이 존재하므로 신용도가 높은 금융회사에게만 발행어음 업무를 취급하도록 허용된다. 현재 우리나라 금융당국은 발행어음의 신용위험 최소화를 위해 은 행과 자기자본 4조원 이상의 갖추고 종합금융투자사업자로 지정된 대형 증권사에게만 발행어음 업무를 허용하고 있다.','','ㅂㅎㅇㅇ',ARRAY['자본시장법','종합금융투자사업자']::text[]),
(229,'발행중지화폐/유통정지화폐','발행중지화폐는 발권기관인 한국은행이 화폐의 원활한 유통 등을 위해 발행을 중지하기로 한 화폐이다.','발행중지화폐는 발권기관인 한국은행이 화폐의 원활한 유통 등을 위해 발행을 중지하기로 한 화폐이다. 발행중지화폐는 비록 화폐 발행은 중단되지만 화폐로서의 강제통용력도 있고 지급결제수단으로 사용도 가능하다. 또한 발행중지화폐는 한국은행 및 금융기관에서 현행 사용하고 있는 화폐와 ‘액면가’로 교환할 수 있다. 이에 반해 유통정지화폐는 화폐 발행을 중단할 뿐만 아니라 시중에서의 사용도 정지된 화폐이다. 즉 화폐로서의 강제통용력이 상실되어 지급결제수단으로 사용할 수 없다. 현재 우리나라 화폐 중 1962 년 제2차 통화조치 이전에 발행된 화폐들은 화폐로서의 효력이 상실된 유통정지화폐이고 1962년 제2차 통화조치 이후에 발행된 화폐 중 현재 사용하고 있는 은행권 4종류(오만원권, 만원권, 오천원권, 천원권)와 주화 6종류(오백원화, 백원화, 오십원화, 십원화, 오원화, 일원화)를 제외한 모든 화폐는 발행중지화폐이다.','','ㅂㅎㅈㅈㅎㅍ/ㅇㅌㅈㅈㅎㅍ',ARRAY['제1차 통화조치','제2차 통화조치']::text[]),
(230,'방카슈랑스','방카슈랑스(Bancassurance)라는 말은 유럽에서 만들어지고 발전된 개념으로 은행을 의 미하는 프랑스어 Banque와 보험을 의미하는 Assurance의 합성어이다.','방카슈랑스(Bancassurance)라는 말은 유럽에서 만들어지고 발전된 개념으로 은행을 의 미하는 프랑스어 Banque와 보험을 의미하는 Assurance의 합성어이다. 은행과 보험회사가 서로 연결되어 일반 개인에게 폭넓은 금융서비스를 제공하는 시스템을 말하는데, 좁게는 보험회사가 은행 지점을 보험상품의 판매 대리점으로 이용하여 은행원이 직접 보험상품을 파는 것을 말한다. 최근에는 금융권역의 장벽이 낮아지는 추세를 보이며 은행뿐만 아니라 저축은행, 카드사 등과 같은 비은행 금융기관에서도 보험을 판매하는 사례가 늘고 있다. 또한, 방카슈랑스가 좁은 의미로는 보험상품의 판매에 국한되지만 넓은 의미로는 은행과 보험사 간의 공동 상품개발이나 종합적인 업무제휴도 포함한다. 고객은 금융기관방문으로 더욱 다양한 금융서비스를 제공받을 수 있고 은행을 통해 저렴하게 보험상품을 구입할 수 있게 되었으며, 은행과 보험상품을 조합해 효율적으로 리스크를 관리할 수 있다는 장점이 있다. 유럽에서는 1980년대 중반부터 점차 확대되었고, 일본은 2001년부터자회사의 일부 보험상품에 한해 판매제휴를 허용하였으며, 우리나라는 2003년 8월부터시행되었다. 이론적으로 어떤 상품을 따로 만들 때 보다 함께 생산할 때 평균비용을 절감할 수 있고 시너지 효과를 얻는 것을 범위의 경제(economy of scope)라고 하는데 은행과 보험의 제휴도 이러한 사례에 속한다. 그동안의 운용경험으로 보아 은행과 증권의 겸업에 비해서는 시장충격이 크지 않았던 것으로 평가되는데 이는 그만큼 보험업의 고유성격이 강하여 은행상품과의 경합관계가 높지 않은데 기인한 것으로 보인다.','','ㅂㅋㅅㄹㅅ',ARRAY['범위의 경제']::text[]),
(231,'배당할인모형','배당할인모형(Dividend Discount Model)은 주식투자에 따라 발생하는 미래의 현금흐름을 적절한 할인율을 적용하여 현재가치로 전환함으로써 주식의 현재가치를 평가하는 모형이다.','배당할인모형(Dividend Discount Model)은 주식투자에 따라 발생하는 미래의 현금흐름을 적절한 할인율을 적용하여 현재가치로 전환함으로써 주식의 현재가치를 평가하는 모형이다. 주식투자에 따른 현금흐름은 보유기간 중의 배당금과 매도할 경우의 주식뱅크런가격으로 구성되는데 만일 보유기간이 매우 길다면 매도할 주식가격의 현재가치는 0에 수렴하게 된다. 일반적으로 주식은 만기가 없는 영구적인 증권이므로 보유기간을 무한대로 상정할 수 있다. 따라서 주식의 가치는 각 기별 배당금을 적절한 할인율(주식투자의 요 구수익률이라고 함)로 할인한 현재가치의 합으로 볼 수 있다. 배당할인모형은 주식가치평가모형 중 가장 기본적인 모형으로서 주식가격 형성에 있어서 핵심 요인이 무엇인지를 보여준다. 그러나 기업경영 및 이익에 관한 수많은 불확실성 등으로 인해 먼 미래의 배당금을 추정하는 것은 불가능에 가깝다. 이러한 문제점을 극복하기 위해 Myron Gordon은 배당금이 일정률로 성장한다는 가정을 기초로 정률성장배당할인모형(Constant Growth Dividend Discount Model)을 제시하였다. Gordon의 모형에 따르면 현재 주식의 가치 (P0), 최근 예상배당(D1), 주식투자의 요구수익률(r), 배당성장률(g) 간에는 P0=D1/(r-g) 의 관계가 성립한다. ㅂ','','ㅂㄷㅎㅇㅁㅎ',ARRAY['배당금','할인율']::text[]),
(232,'밴드웨건효과','소비자가 대중적으로 유행하는 정보를 쫓아 상품을 구매하는 현상을 말한다.','소비자가 대중적으로 유행하는 정보를 쫓아 상품을 구매하는 현상을 말한다. 악대차 (band wagon)가 악단을 선도하며 요란한 연주로 하면 이 밴드왜건을 우르르 쫓아가 는 사람들의 모습에서 밴드웨건효과라는 말이 만들어졌다. 밴드웨건효과(Bandwagon Effect)는 결국 유행에 동조함으로써 타인들과의 관계에서 소외되지 않으려는 비이성적인 심리에서 비롯된다. 주식시장이나 부동산시장의 거품형성과 붕괴현상도 밴드웨건효과 로 설명할 수 있다.','','ㅂㄷㅇㄱㅎㄱ',ARRAY['속물효과(스놉효과)','베블런효과']::text[]),
(233,'뱅크런','은행의 대규모 예금인출사태를 가리키는 말이다.','은행의 대규모 예금인출사태를 가리키는 말이다. 금융시장 상황이 불안하거나 은행의 경영 및 건전성 등에 문제가 발생하면, 예금자들은 은행에 맡긴 돈을 보장받을 수 없을 것이 라는 불안감으로 인해 저축한 돈을 급격히 인출하게 된다. 이로 인해 은행은 일시적으로 지급할 수 있는 자금이 부족하게 되어 패닉 상태에 빠질 수 있다. 이를 뱅크런(Bank Run) 이라 부르며 우리나라의 예금보험공사는 뱅크런과 이로 인한 금융불안을 예방하기 위해예금자보호법에 의해 1억 원까지의 예금을 보호해주고 있다.','','ㅂㅋㄹ',ARRAY['예금보험제도']::text[]),
(234,'범위의 경제','개별 기업이 한 종류의 제품만을 생산하는 경우보다 여러 제품을 같이 생산하면서 평균생산비용이 적게 들 때 범위의 경제(Economies of Scope)가 존재한다고 말한다.','개별 기업이 한 종류의 제품만을 생산하는 경우보다 여러 제품을 같이 생산하면서 평균생산비용이 적게 들 때 범위의 경제(Economies of Scope)가 존재한다고 말한다. 승용차와 트럭을 같이 생산하는 기업의 경우 소재부품이나 조립라인 등의 생산시설을 공동으로 사용할 수 있는 이점을 갖게 된다. 이러한 현상은 동일한 생산요소를 사용하거나 기업운영 및 마케팅 활동을 함께 하거나 생산물이 가진 특성 때문에도 나타날 수 있다. 연구개발·판매·생산은 공동으로 하면서 제품의 종류만 달리할 경우 비용이 절감될 수 있다. 또한 기존 산업과 비슷한 산업에 진출할 경우 시너지효과를 기대할 수 있는데, 구체적인 예로는 은행이 보험 상품을 판매하는 방카슈랑스를 들 수 있다.','','ㅂㅇㅇㄱㅈ',ARRAY['규모의 경제']::text[]),
(235,'법정화폐','법정화폐(Legal Tender)란 법률에 의해 인정되는 공적 지불수단의 성격을 지닌 화폐를 의미한다.','법정화폐(Legal Tender)란 법률에 의해 인정되는 공적 지불수단의 성격을 지닌 화폐를 의미한다. 다시 말해 국가가 법률로 부채의 상환, 상품 구매, 세금 납부 등에 있어서 반드시 수령하고 경제적 거래가 완결됨을 의미한다. 국가마다 법정화폐로 인정되는 범위가 다 른데 우리나라의 경우 한국은행법 제48조에서 “한국은행이 발행한 한국은행권은 법화(法 貨)로서 모든 거래에 무제한 통용된다.”고 규정함으로써 한국은행권이 모든 경제적 거래에서 법정화폐로 인정된다. 그러나 법정화폐 수령 거부에 대한 처벌 조항이 없는 데다 신용카드, 실시간 계좌이체 등 전자결제 수단에 대한 선호, 큰 금액의 채무를 소액 주화를 대량으로 지급하여 수령인의 불편을 초래하는 행위에 대한 사회적 반감 등으로 한국은행권이 완전한 법정화폐로서 기능하는 데에는 현실적인 한계가 존재한다. 변동금리','','ㅂㅈㅎㅍ','{}'::text[]),
(236,'베버리지곡선','베버리지곡선(Beveridge Curve)은 노동 공급(실업률) 및 수요(빈일자리율) 간 관계를 나 타내는 곡선으로 이를 통하여 노동수급 상황과 노동시장의 효율성 정도를 파악할 수 있다.','베버리지곡선(Beveridge Curve)은 노동 공급(실업률) 및 수요(빈일자리율) 간 관계를 나 타내는 곡선으로 이를 통하여 노동수급 상황과 노동시장의 효율성 정도를 파악할 수 있다. 실업과 빈일자리 간 미스매치를 언급한 영국 경제학자 베버리지(W. Beveridge)를 따라서 명명된 베버리지곡선은 통상 실업률이 높아지면 빈일자리율이 줄어들고, 실업률이 낮아지면 빈일자리율은 늘어나는 관계가 있다. 이는 실업률을 X축, 빈일자리율을 Y축으로 할 때, 경기 확장기에서처럼 유휴노동력이 축소되면 실업율이 줄어들고 빈일자리율은 늘어나며, 경기 수축기에서 나타나듯이 유후노동력이 늘어나면 실업률이 늘어나고 빈일자리율은 줄어드는 특성에 기인한다. 한편 노동시장 내 마찰적 요인의 증가로 구인·구직자 간 매칭 효율성이 낮아질 경우 실업률과 빈일자리율이 동시에 높아져 곡선 자체가 오 ㅂ 른쪽 상방으로 이동할 수 있다.','','ㅂㅂㄹㅈㄱㅅ','{}'::text[]),
(237,'베블런효과','가격이 상승하면 수요량이 감소하는 수요 법칙에 반하는 재화를 베블런재라 부른다.','가격이 상승하면 수요량이 감소하는 수요 법칙에 반하는 재화를 베블런재라 부른다. 사치재, 명품 등이 이에 해당하는데 이러한 재화는 가격이 비쌀수록 소비가 증가하는 경향이 있다. 이러한 과시 욕구를 반영한 소비현상을 베블런효과(Veblen’s Effect)라고 부른다. 베블런은 이러한 현상을 처음으로 관찰한 학자의 이름이다.','','ㅂㅂㄹㅎㄱ',ARRAY['기펜재','밴드웨건효과']::text[]),
(238,'변동금리','변동금리란 시장금리를 반영하여 일정 주기별로 약정금리가 변하는 금리를 의미하며, 고 정금리란 최초 약정한 금리가 만기 때까지 그대로 유지되는 금리를 의미한다.','변동금리란 시장금리를 반영하여 일정 주기별로 약정금리가 변하는 금리를 의미하며, 고 정금리란 최초 약정한 금리가 만기 때까지 그대로 유지되는 금리를 의미한다. 예를 들어 만기 1년, 약정금리는 4%의 고정금리라면 약정기간 1년 동안 시장금리가 어떻게 변하더라도 해당 약정금리는 4%이다. 반면 만기 1년, 변동주기 3개월, 약정금리는 CD금리+0.5%(또는 50bp)의 변동금리라면 3개월에 한 번씩 변동된 CD금리에 연동하여 약정금리가 변하게 된다. 예를 들어 CD금리가 최초 약정시 3.0%, 약정 3개월 후 3.2%, 6개월 후 3.5%, 9개월 후 4.0%라면 약정금리는 최초 약정시 3.5%, 약정 3개월 후 3.7%, 6개월 후 4.0%, 9개월 후 4.5%가 된다. 자금 차입자 입장에서는 앞으로 시장금리가 상승할 것으로 예상하는 경우에는 고정금리를 이용하는 것이 유리하고 시장금리가 하락할 것으로 예상하는 경우에는 변동금리를 이용하는 것이 유리하다. 일반적으로 동일 만기에서 는 고정금리가 변동금리보다 높은데 이는 자금 대여자(은행)에게 약정 기간 중 금리 변동에 따른 위험 프리미엄이 존재하기 때문이다. 한편 변동금리의 준거가 되는 금리는 CD금리가 주로 적용되었으나 지금은 COFIX와 은행채 금리도 많이 활용되고 있다.','','ㅂㄷㄱㄹ',ARRAY['고정금리부채권(SB)']::text[]),
(239,'보복소비','보복소비(Revenge Spending 혹은 Pent-up Demand)란 상당 기간 소비 기회가 막혀강제적으로 소비가 제한되거나 혹은 소비가 억제됨에 따른 피로 누적과 이에 대한 보상보완재욕구…','보복소비(Revenge Spending 혹은 Pent-up Demand)란 상당 기간 소비 기회가 막혀강제적으로 소비가 제한되거나 혹은 소비가 억제됨에 따른 피로 누적과 이에 대한 보상보완재욕구, 미래 소비기회 상실 우려 등에 대한 반작용으로 소비가 급격하게 늘어나는 것을 의 미한다. 최근 코로나19로 억눌렸던 소비 욕구 및 수요가 보복하듯 한꺼번에 분출하는 현상을 지칭하기 위하여 널리 쓰여지게 되었다. 2020년 중국 언론과 소비 트렌드 분석에서 처음 부각된 것으로 알려져 있다.','','ㅂㅂㅅㅂ','{}'::text[]),
(240,'보완자본(Tier 2)','국제결제은행(BIS)의 기준에 따른 은행의 자기자본(=기본자본+보완자본)을 구성하는 요 소로서, 기본자본에 비해 손실흡수능력이 떨어지지만 예상외 손실로 은행이 파산할 경우예금자를 포함한…','국제결제은행(BIS)의 기준에 따른 은행의 자기자본(=기본자본+보완자본)을 구성하는 요 소로서, 기본자본에 비해 손실흡수능력이 떨어지지만 예상외 손실로 은행이 파산할 경우예금자를 포함한 일반채권자에 앞서 손실을 흡수(혹은 은행의 청산 시 은행의 손실을 보전)할 수 있는 자기자본(gone-concern capital)을 의미한다. 보완자본은 해당하는 요건 ㅂ 을 충족하는 보완자본증권 및 이와 관련된 자본잉여금, 자회사가 발행한 보완자본증권의 일부 제3자 보유분, 특정 요건을 충족하는 대손충당금 등으로 구성된다. 해당 은행이 발행한 증권이 보완자본증권으로 인정받기 위해서는 예금자·일반채권자보다 후순위일 것, 최저만기 5년 이상이고 금리 상향조정을 비롯한 중도상환 유인이 없을 것 등의 요건을 충족해야 한다(참고 「은행업감독업무시행세칙」별표 3). 아울러 신용리스크 측정시 표준방법을 사용하는 은행이 설정한 일반 대손충당금(general provisions)과 내부등급법 사용은행이 예상손실을 초과하여 적립한 적격 대손충당금은 규제자본과 동일하게 예상외 손실을 흡수하는 데 사용할 수 있다고 간주하여 일정 범위(각각 신용위험가중자산의 1.25% 및 0.6%) 내에서 보완자본(supplementary capital)에 가산할 수 있다.','','ㅂㅇㅈㅂ()',ARRAY['BIS 자기자본비율','기본자본(Tier 1)']::text[]);
